10: export async function computeHealthStatus(
11:   config: ServerConfig,
12:   startTime: number,
13:   checkers: DependencyCheckers = {},
14: ): Promise<{ status: HealthStatus; httpStatus: number }> {
15:   // If external dependencies are not configured, they are "not_configured"
16:   let dbStatus: HealthComponentStatus = config.MONGODB_URI ? "ok" : "not_configured";
17:   if (config.MONGODB_URI && checkers.checkDb) {
18:     try {
19:       dbStatus = await checkers.checkDb();
20:     } catch {
21:       dbStatus = "unavailable";
22:     }
23:   }
24: 
25:   let modelStatus: HealthComponentStatus = "not_configured";
26:   if (config.OLLAMA_BASE_URL && checkers.checkModel) {
27:     try {
28:       modelStatus = await checkers.checkModel();
29:     } catch {
30:       modelStatus = "unavailable";
31:     }
32:   }
33: 
34:   let scoresStatus: HealthComponentStatus = "not_configured";
35:   if (checkers.checkScores) {
36:     try {
37:       scoresStatus = await checkers.checkScores();
38:     } catch {
39:       scoresStatus = "unavailable";
40:     }
41:   }
42: 
43:   // Any configured dependency that is unavailable causes overall degradation/503
44:   const hasUnavailableConfigured =
45:     dbStatus === "unavailable" || modelStatus === "unavailable" || scoresStatus === "unavailable";
46: 
47:   const isDemoMode = !config.MONGODB_URI;
48: 
49:   const overallStatus = hasUnavailableConfigured ? "unavailable" : "ok";
50:   const httpStatus = hasUnavailableConfigured ? 503 : 200;
51: 
52:   const healthPayload: HealthStatus = {
53:     status: overallStatus,
54:     uptime: Math.floor((Date.now() - startTime) / 1000),
55:     timestamp: new Date().toISOString(),
56:     mode: isDemoMode ? "demo" : "configured",
57:     checks: {
58:       db: dbStatus,
59:       model: modelStatus,
60:       scores: scoresStatus,
61:     },
62:   };
63: 
64:   return { status: healthPayload, httpStatus };
