import React, { useState, useEffect } from "react";

export interface NavigationProps {
  currentRoute: string;
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemoModal?: () => void;
}

export const TopBar: React.FC<NavigationProps> = ({
  currentRoute,
  onRouteChange,
  onOpenDemoModal,
}) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Primary navigation items according to simplified hierarchy
  const primaryNavItems = [
    { id: "landing", label: "Archive" },
    { id: "archive", label: "Chambers" },
    { id: "integrations", label: "Integrations" },
    { id: "about", label: "Safety" },
  ];

  // Additional vault experiences preserved for drawer / deep links
  const secondaryVaultItems = [
    { id: "dashboard", label: "Investigator Vault" },
    { id: "upload", label: "Intake Ledger" },
    { id: "setup", label: "AI Investigation Profile" },
    { id: "spirit", label: "Free Spirit Interlude" },
  ];

  const handleNav = (id: string) => {
    onRouteChange(id);
    setMobileMenuOpen(false);
  };

  // Close mobile drawer on Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && mobileMenuOpen) {
        setMobileMenuOpen(false);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [mobileMenuOpen]);

  return (
    <header
      style={{
        height: "86px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "16px",
        padding: "10px clamp(16px, 3vw, 42px)",
        borderBottom: "1px solid rgba(197, 160, 89, 0.35)",
        background: "linear-gradient(180deg, rgba(13, 13, 17, 0.96), rgba(8, 8, 10, 0.98))",
        position: "sticky",
        top: 0,
        zIndex: 50,
        backdropFilter: "blur(14px)",
      }}
    >
      {/* Brand logo + Title */}
      <div
        onClick={() => handleNav("landing")}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            handleNav("landing");
          }
        }}
        aria-label="Keys of the Departed sanctuary home"
        style={{
          display: "flex",
          alignItems: "center",
          gap: "12px",
          cursor: "pointer",
          minWidth: "250px",
        }}
      >
        <img
          src="/logo.png"
          alt="Keys of the Departed emblem"
          style={{
            width: "50px",
            height: "54px",
            objectFit: "contain",
            filter: "drop-shadow(0 0 10px rgba(197, 160, 89, 0.35))",
          }}
        />
        <div>
          <div
            className="display"
            style={{
              fontSize: "17px",
              fontWeight: 700,
              letterSpacing: "0.06em",
              color: "#f7ebd2",
              textShadow: "0 2px 4px rgba(0,0,0,0.9)",
              lineHeight: 1.1,
            }}
          >
            KEYS OF THE DEPARTED
          </div>
          <div
            className="serif"
            style={{
              fontSize: "12px",
              fontStyle: "italic",
              color: "#c7b591",
              marginTop: "2px",
            }}
          >
            The engineer left. Their access didn&apos;t.
          </div>
        </div>
      </div>

      {/* Primary Desktop Navigation Links */}
      <nav
        className="desktop-nav"
        aria-label="Primary sanctuary navigation"
        style={{ display: "flex", alignItems: "center", gap: "8px" }}
      >
        {primaryNavItems.map((item) => {
          const isActive = currentRoute === item.id || (item.id === "landing" && currentRoute === "");
          return (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className="display"
              aria-current={isActive ? "page" : undefined}
              style={{
                background: "transparent",
                border: "none",
                borderBottom: isActive ? "2px solid var(--gold)" : "2px solid transparent",
                color: isActive ? "var(--gold2)" : "#c8b994",
                padding: "8px 14px",
                fontSize: "11.5px",
                fontWeight: 600,
                letterSpacing: "0.07em",
                textTransform: "uppercase",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
            >
              {item.label}
            </button>
          );
        })}
      </nav>

      {/* Right Secondary Actions: Demo Tour, Sign In, Sign Up */}
      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
        {onOpenDemoModal && (
          <button
            onClick={onOpenDemoModal}
            className="btn small"
            id="topbar-btn-demo"
            style={{
              background: "linear-gradient(180deg, #8b1e2d, #521019)",
              borderColor: "var(--gold)",
              boxShadow: "0 0 14px rgba(139, 30, 45, 0.4)",
              whiteSpace: "nowrap",
            }}
          >
            ✦ Demo Tour
          </button>
        )}

        <button
          onClick={() => handleNav("auth")}
          className="btn ghost small desktop-auth"
          id="topbar-btn-signin"
          style={{
            textTransform: "uppercase",
            borderColor: currentRoute === "auth" || currentRoute === "signin" ? "var(--gold)" : undefined,
            color: currentRoute === "auth" || currentRoute === "signin" ? "var(--cream)" : undefined,
          }}
        >
          Sign In
        </button>

        <button
          onClick={() => handleNav("signup")}
          className="btn small secondary desktop-auth"
          id="topbar-btn-signup"
          style={{ textTransform: "uppercase", fontSize: "10px" }}
        >
          Sign Up
        </button>

        {/* Mobile Hamburger Button */}
        <button
          className="mobile-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label={mobileMenuOpen ? "Close navigation menu" : "Open navigation menu"}
          aria-expanded={mobileMenuOpen}
          aria-controls="mobile-navigation-drawer"
          style={{
            background: "transparent",
            border: "1px solid var(--line)",
            color: "var(--gold2)",
            padding: "8px 12px",
            fontSize: "18px",
            cursor: "pointer",
            borderRadius: "3px",
            display: "none",
          }}
        >
          {mobileMenuOpen ? "✕" : "☰"}
        </button>
      </div>

      {/* Mobile Drawer Menu */}
      {mobileMenuOpen && (
        <div
          id="mobile-navigation-drawer"
          role="dialog"
          aria-modal="true"
          aria-label="Sanctuary navigation drawer"
          style={{
            position: "absolute",
            top: "86px",
            left: 0,
            right: 0,
            background: "rgba(13, 13, 17, 0.98)",
            borderBottom: "1px solid var(--gold)",
            padding: "20px 24px 28px",
            display: "flex",
            flexDirection: "column",
            gap: "10px",
            zIndex: 100,
            backdropFilter: "blur(16px)",
            boxShadow: "0 20px 40px rgba(0,0,0,0.8)",
          }}
        >
          <div className="eyebrow" style={{ color: "var(--gold)", fontSize: "10px", marginBottom: "4px" }}>
            PRIMARY ARCHIVE NAVIGATION
          </div>
          {primaryNavItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className="display"
              aria-current={currentRoute === item.id ? "page" : undefined}
              style={{
                background: "transparent",
                border: "none",
                color: currentRoute === item.id ? "var(--gold2)" : "#c8b994",
                padding: "10px 6px",
                textAlign: "left",
                fontSize: "13px",
                cursor: "pointer",
                borderBottom: "1px solid rgba(197, 160, 89, 0.15)",
              }}
            >
              {item.label}
            </button>
          ))}

          <div className="eyebrow" style={{ color: "#a99b82", fontSize: "10px", marginTop: "10px", marginBottom: "4px" }}>
            VAULT SECTIONS & TOOLS
          </div>
          {secondaryVaultItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className="serif"
              style={{
                background: "transparent",
                border: "none",
                color: currentRoute === item.id ? "var(--gold2)" : "#a99b82",
                padding: "8px 6px",
                textAlign: "left",
                fontSize: "13px",
                cursor: "pointer",
                borderBottom: "1px solid rgba(197, 160, 89, 0.1)",
              }}
            >
              {item.label}
            </button>
          ))}

          <div style={{ display: "flex", gap: "10px", marginTop: "14px" }}>
            <button
              onClick={() => handleNav("auth")}
              className="btn ghost small"
              style={{ flex: 1 }}
            >
              Sign In
            </button>
            <button onClick={() => handleNav("signup")} className="btn small" style={{ flex: 1 }}>
              Sign Up
            </button>
          </div>
        </div>
      )}

      {/* Responsive Breakpoints CSS */}
      <style>{`
        @media (max-width: 900px) {
          .desktop-nav {
            display: none !important;
          }
          .desktop-auth {
            display: none !important;
          }
          .mobile-toggle {
            display: block !important;
          }
        }
      `}</style>
    </header>
  );
};

