22: /**
23:  * Sanitizes return URLs to completely prevent open redirect vulnerabilities.
24:  * Never allows external schemes, protocol-relative URLs, or script injection.
25:  */
26: export function sanitizeReturnUrl(url?: string | null): string {
27:   if (!url || typeof url !== "string") return "landing";
28:   const trimmed = url.trim();
29: 
30:   // Explicitly disallow dangerous schemes, protocol-relative urls, or traversal
31:   if (
32:     trimmed.startsWith("//") ||
33:     trimmed.startsWith("http://") ||
34:     trimmed.startsWith("https://") ||
35:     trimmed.startsWith("javascript:") ||
36:     trimmed.startsWith("data:") ||
37:     trimmed.includes("..")
38:   ) {
39:     return "landing";
40:   }
41: 
42:   // Strip leading slash or hash
43:   const cleanRoute =
44:     trimmed
45:       .replace(/^[#/]+/, "")
46:       .split("?")[0]
47:       ?.split("/")[0] || "";
48: 
49:   if (SAFE_INTERNAL_ROUTES.has(cleanRoute)) {
50:     return cleanRoute;
51:   }
52: 
53:   // Allow case demo IDs e.g. case_demo_01
54:   if (/^case_[a-zA-Z0-9_-]+$/.test(cleanRoute)) {
55:     return cleanRoute;
56:   }
57: 
58:   return "landing";
59: }
