63:  */
64: export function validateEmail(email: string): {
65:   isValid: boolean;
66:   error?: string;
67:   sanitized: string;
68: } {
69:   const trimmed = email.trim();
70: 
71:   if (!trimmed) {
72:     return { isValid: false, error: "Investigator identifier / email is required.", sanitized: "" };
73:   }
74: 
75:   if (trimmed.length > 254) {
76:     return {
77:       isValid: false,
78:       error: "Email address exceeds the maximum length of 254 characters.",
79:       sanitized: trimmed,
80:     };
81:   }
82: 
83:   // Standard RFC-compatible pattern: user@domain.tld with support for tags and dots
84:   const emailRegex =
85:     /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
