args.CodeContent:
const fs = require('fs');
const path = require('path');
const dir = 'E:/keys-of-the-departed/assets';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.png') || f.endsWith('.jpg'));

function getDimensions(filePath) {
  const buf = fs.readFileSync(filePath);
  if (filePath.endsWith('.png')) {
    const width = buf.readUInt32BE(16);
    const height = buf.readUInt32BE(20);
    return { width, height };
  } else if (filePath.endsWith('.jpg')) {
    let offset = 2;
    while (offset < buf.length) {
      if (buf[offset] !== 0xFF) break;
      const marker = buf[offset + 1];
      if (marker === 0xC0 || marker === 0xC2) {
        const height = buf.readUInt16BE(offset + 5);
        const width = buf.readUInt16BE(offset + 7);
        return { width, height };
      }
      offset += 2 + buf.readUInt16BE(offset + 2);
    }
  }
  return null;
}

const results = {};
files.forEach(f => {
  const d = getDimensions(path.join(dir, f));
  results[f] = d ? `${d.width}x${d.height}` : 'unknown';
  console.log(`${f}: ${results[f]}`);
});

