import React, { useState, useEffect } from "react";

export interface FreeSpiritPageProps {
  onRouteChange: (route: string) => void;
}

export interface RitualStatement {
  id: number;
  title: string;
  statement: string;
  trait: string;
  symbol: string;
}

export const RITUAL_STATEMENTS: RitualStatement[] = [
  {
    id: 1,
    title: "Fragment I · The Hidden Corner",
    statement: "I like to explore new ideas and hidden corners before I have all the answers.",
    trait: "Curiosity",
    symbol: "✦",
  },
  {
    id: 2,
    title: "Fragment II · The Overlooked Timestamp",
    statement: "I often notice small discrepancies, timestamps, and commit signatures that others overlook.",
    trait: "Precision",
    symbol: "◈",
  },
  {
    id: 3,
    title: "Fragment III · The Independent Path",
    statement: "I prefer carving my own investigative path instead of relying on rigid, pre-cooked rules.",
    trait: "Independence",
    symbol: "▲",
  },
  {
    id: 4,
    title: "Fragment IV · The Human Story",
    statement: "I care about the human stories, intentions, and memories behind abandoned systems.",
    trait: "Empathy",
    symbol: "♥",
  },
  {
    id: 5,
    title: "Fragment V · The Patient Watch",
    statement: "I can sit comfortably with uncertainty while waiting for verifiable evidence.",
    trait: "Patience",
    symbol: "☽",
  },
];

export interface ArchetypeResult {
  title: string;
  subtitle: string;
  desc: string;
  asset: string;
  philosophy: string;
}

/**
 * Deterministic computation of the investigator archetype based on resonant choice count.
 */
export function computeArchetype(selectedCount: number): ArchetypeResult {
  switch (selectedCount) {
    case 5:
      return {
        title: "Free Spirit",
        subtitle: "The Unshackled Inquirer",
        desc: "Unbound by rigid dogma, you balance radical empathy with uncompromising evidence verification. You give abandoned systems their historical dignity while refusing to assume what cannot be proven.",
        asset: "/heart-bleeding-gothic.png",
        philosophy: "The past deserves truth, not mere condemnation.",
      };
    case 4:
      return {
        title: "Unbound Archivist",
        subtitle: "The Independent Investigator",
        desc: "You follow evidence across forgotten repositories where standard rule engines fail. You treat each credential not as a generic vulnerability score, but as a human artifact waiting for an authentic provenance record.",
        asset: "/rose-crimson-gold.png",
        philosophy: "Every signature tells a story if one knows where to look.",
      };
    case 3:
      return {
        title: "Keeper of Small Wonders",
        subtitle: "The Chronicler of Forgotten Lore",
        desc: "You find depth in silent bots, legacy cron tokens, and forgotten commit messages. You assemble the fragmented pieces of engineering history until the full lineage becomes undeniably clear.",
        asset: "/goldenbook.png",
        philosophy: "No line of history is too small to be recorded.",
      };
    case 2:
      return {
        title: "Curious Wanderer",
        subtitle: "The Explorer of Shadow Repositories",
        desc: "Drawn by intuition and sharp pattern recognition, you wander through legacy codebases to uncover why systems were originally architected before passing final judgment.",
        asset: "/moon-waxing-crescent.png",
        philosophy: "Understanding begins before the first conclusion is drawn.",
      };
    case 1:
    default:
      return {
        title: "Quiet Observer",
        subtitle: "The Guardian of Restrained Evidence",
        desc: "You walk the quiet margins of the vault, listening before speaking. You refuse to fabricate certainty where audit records are silent, trusting patience above premature closure.",
        asset: "/candleon.png",
        philosophy: "Where records are silent, the archivist must abstain.",
      };
  }
}

export const FreeSpiritPage: React.FC<FreeSpiritPageProps> = ({ onRouteChange }) => {
  // Ritual step states: -1 = unlit intro, 0..4 = statements 1..5, 5 = reveal
  const [currentStep, setCurrentStep] = useState<number>(-1);
  const [candleLit, setCandleLit] = useState<boolean>(false);
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
  const [copyFeedback, setCopyFeedback] = useState<boolean>(false);

  // Reduced motion preference
  const [prefersReducedMotion, setPrefersReducedMotion] = useState<boolean>(false);

  useEffect(() => {
    if (typeof window !== "undefined") {
      const media = window.matchMedia("(prefers-reduced-motion: reduce)");
      setPrefersReducedMotion(media.matches);
      const listener = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
      media.addEventListener("change", listener);
      return () => media.removeEventListener("change", listener);
    }
  }, []);

  // Kindle the altar candle
  const handleKindleCandle = () => {
    setCandleLit(true);
    if (prefersReducedMotion) {
      setCurrentStep(0);
    } else {
      setTimeout(() => {
        setCurrentStep(0);
      }, 550);
    }
  };

  const toggleResonance = (id: number) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const handleNext = () => {
    if (currentStep < 4) {
      setCurrentStep((prev) => prev + 1);
    } else {
      setCurrentStep(5); // reveal step
    }
  };

  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    } else if (currentStep === 0) {
      setCurrentStep(-1);
      setCandleLit(false);
    }
  };

  const handleReset = () => {
    setSelectedIds(new Set());
    setCurrentStep(-1);
    setCandleLit(false);
    setCopyFeedback(false);
  };

  const archetype = computeArchetype(selectedIds.size);

  const handleCopyResult = async () => {
    const text = `✦ Keys of the Departed — Archival Archetype ✦\nArchetype: ${archetype.title} (${archetype.subtitle})\nPhilosophy: "${archetype.philosophy}"\nResonant Choices: ${selectedIds.size} of 5 archive fragments.\n(Playful archive interlude; does not affect machine-identity security classifications.)`;
    try {
      if (navigator.clipboard) {
        await navigator.clipboard.writeText(text);
        setCopyFeedback(true);
        setTimeout(() => setCopyFeedback(false), 3000);
      }
    } catch {
      // Graceful fallback
    }
  };

  return (
    <div
      className="animate-fade-in"
      style={{
        minHeight: "calc(100vh - 86px)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: "40px clamp(16px, 4vw, 40px)",
        position: "relative",
        overflowX: "hidden",
      }}
    >
      {/* Background Architectural Watermark */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "min(640px, 94vw)",
          height: "min(720px, 90vh)",
          backgroundImage: "url('/windowframe.png')",
          backgroundSize: "contain",
          backgroundRepeat: "no-repeat",
          backgroundPosition: "center",
          opacity: 0.06,
          pointerEvents: "none",
          filter: "drop-shadow(0 0 30px rgba(197, 160, 89, 0.2))",
        }}
      />

      {/* Main Ritual Chamber Container */}
      <div
        className="panel"
        style={{
          maxWidth: "720px",
          width: "100%",
          padding: "clamp(28px, 5vw, 44px)",
          position: "relative",
          border: "1px solid var(--gold)",
          borderRadius: "4px",
          boxShadow: "0 25px 80px rgba(0, 0, 0, 0.9), 0 0 35px rgba(197, 160, 89, 0.15)",
          background:
            "linear-gradient(175deg, rgba(22, 18, 25, 0.98) 0%, rgba(13, 11, 15, 0.99) 100%)",
          zIndex: 2,
        }}
      >
        {/* ================= STAGE 1: OPENING SCENE (UNLIT CANDLE) ================= */}
        {currentStep === -1 && (
          <div style={{ textAlign: "center" }} className="animate-fade-in">
            <div
              className="eyebrow"
              style={{ color: "var(--gold)", letterSpacing: "0.22em", marginBottom: "8px" }}
            >
              ✦ THE KEEPER&apos;S RITUAL · ARCHIVE INTERLUDE ✦
            </div>

            <h1
              className="display"
              style={{
                fontSize: "clamp(24px, 4vw, 36px)",
                color: "#f7ebd2",
                margin: "10px 0 16px",
                letterSpacing: "0.05em",
                textShadow: "0 2px 14px rgba(0, 0, 0, 0.9)",
              }}
            >
              Awaken the Altar
            </h1>

            <p
              className="serif"
              style={{
                fontSize: "17px",
                color: "#d0bd98",
                maxWidth: "540px",
                margin: "0 auto 28px",
                lineHeight: 1.55,
                fontStyle: "italic",
              }}
            >
              Step into the quietest corner of the archive. Here, no machine identities are judged.
              Kindle the altar flame to discover which archival instinct guides your investigation.
            </p>

            {/* Interactive Altar Candle */}
            <div
              role="button"
              tabIndex={0}
              id="ritual-candle-unlit"
              aria-label="Kindle the altar candle to begin the ritual"
              onClick={handleKindleCandle}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleKindleCandle();
                }
              }}
              style={{
                display: "inline-flex",
                flexDirection: "column",
                alignItems: "center",
                cursor: "pointer",
                padding: "16px 24px",
                borderRadius: "8px",
                outline: "none",
                background: "rgba(0, 0, 0, 0.35)",
                border: "1px dashed rgba(197, 160, 89, 0.35)",
                transition: "all 0.3s ease",
                margin: "0 auto 28px",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = "var(--gold)";
                e.currentTarget.style.boxShadow = "0 0 25px rgba(197, 160, 89, 0.25)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = "rgba(197, 160, 89, 0.35)";
                e.currentTarget.style.boxShadow = "none";
              }}
            >
              <img
                src={candleLit ? "/candleon.png" : "/candleoff.png"}
                alt={candleLit ? "Kindled altar candle" : "Unlit altar candle"}
                className={candleLit ? "candle-glow" : undefined}
                style={{
                  width: "56px",
                  height: "92px",
                  objectFit: "contain",
                  transition: "transform 0.4s ease, filter 0.4s ease",
                  transform: candleLit ? "scale(1.08)" : "scale(1)",
                  filter: candleLit
                    ? "drop-shadow(0 0 20px rgba(240, 213, 154, 0.8))"
                    : "drop-shadow(0 4px 12px rgba(0,0,0,0.7))",
                }}
              />
              <span
                className="eyebrow"
                style={{
                  marginTop: "12px",
                  color: candleLit ? "var(--gold2)" : "#a99b82",
                  fontSize: "11px",
                  letterSpacing: "0.14em",
                }}
              >
                {candleLit ? "✦ FLAME KINDLED ✦" : "CLICK OR PRESS SPACE TO KINDLE"}
              </span>
            </div>

            <div>
              <button
                type="button"
                onClick={handleKindleCandle}
                className="btn"
                id="btn-begin-ritual"
                style={{
                  padding: "14px 34px",
                  fontSize: "11.5px",
                  letterSpacing: "0.1em",
                }}
              >
                Begin the Ritual <span>✦</span>
              </button>
            </div>

            <div style={{ marginTop: "24px" }}>
              <button
                type="button"
                onClick={() => onRouteChange("archive")}
                className="btn ghost small"
                style={{ fontSize: "11px" }}
              >
                ← Return to Archive Chambers
              </button>
            </div>
          </div>
        )}

        {/* ================= STAGE 2: FIVE INTERACTIVE CHOICES ================= */}
        {currentStep >= 0 && currentStep <= 4 && (
          <div className="animate-fade-in">
            {/* Header with Step Tracker */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                paddingBottom: "16px",
                borderBottom: "1px solid rgba(197, 160, 89, 0.25)",
                marginBottom: "26px",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <img
                  src="/candleon.png"
                  alt="Altar candle"
                  className="candle-glow"
                  style={{ width: "20px", height: "36px", objectFit: "contain" }}
                />
                <span
                  className="eyebrow"
                  style={{ color: "var(--gold2)", fontSize: "10.5px", letterSpacing: "0.18em" }}
                >
                  THE KEEPER&apos;S RITUAL
                </span>
              </div>

              <div
                className="mono"
                style={{
                  fontSize: "12px",
                  color: "#d0bd98",
                  letterSpacing: "0.08em",
                }}
              >
                FRAGMENT {currentStep + 1} OF 5
              </div>
            </div>

            {/* Five Node Progress Bar */}
            <div
              role="tablist"
              aria-label="Ritual fragment navigation"
              style={{
                display: "flex",
                justifyContent: "space-between",
                gap: "8px",
                marginBottom: "32px",
              }}
            >
              {RITUAL_STATEMENTS.map((item, idx) => {
                const isCurrent = idx === currentStep;
                const isSelected = selectedIds.has(item.id);
                return (
                  <button
                    key={item.id}
                    type="button"
                    role="tab"
                    aria-selected={isCurrent}
                    aria-label={`${item.title} ${isSelected ? "(Resonated)" : ""}`}
                    onClick={() => setCurrentStep(idx)}
                    style={{
                      flex: 1,
                      height: "36px",
                      background: isCurrent
                        ? "rgba(197, 160, 89, 0.25)"
                        : isSelected
                          ? "rgba(139, 30, 45, 0.3)"
                          : "rgba(255, 255, 255, 0.04)",
                      border: isCurrent
                        ? "1px solid var(--gold)"
                        : isSelected
                          ? "1px solid var(--crimson2)"
