import React, { useState, useEffect, useRef } from "react";
import { ArchiveAccount, AccountsResponse } from "@keys/contracts";

export interface ArchivePageProps {
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  initialFilter?: string;
}

export const ArchivePage: React.FC<ArchivePageProps> = ({
  onRouteChange,
  initialFilter = "ALL",
}) => {
  const [selectedChapter, setSelectedChapter] = useState<string>(initialFilter);
  const [selectedStatus, setSelectedStatus] = useState<string>("ALL");
  const [searchInput, setSearchInput] = useState<string>("");
  const [debouncedSearch, setDebouncedSearch] = useState<string>("");
  const [currentPage, setCurrentPage] = useState<number>(1);

  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [response, setResponse] = useState<AccountsResponse | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);

  // 1. Debounce search query (~300ms)
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchInput.trim());
      setCurrentPage(1); // Reset page on new search
    }, 300);

    return () => clearTimeout(timer);
  }, [searchInput]);

  // Reset page when chapter or status changes
  const handleChapterChange = (chapter: string) => {
    setSelectedChapter(chapter);
    setCurrentPage(1);
  };

  const handleStatusChange = (status: string) => {
    setSelectedStatus(status);
    setCurrentPage(1);
  };

  // 2. API Data Fetching with AbortController to prevent race conditions
  const fetchAccounts = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    setLoading(true);
    setError(null);

    const params = new URLSearchParams({
      chapter: selectedChapter,
      status: selectedStatus,
      search: debouncedSearch,
      page: String(currentPage),
      limit: "12",
    });

    fetch(`/api/accounts?${params.toString()}`, { signal: controller.signal })
      .then(async (res) => {
        if (!res.ok) {
          const errBody = await res.json().catch(() => ({}));
          throw new Error(
            errBody.error || `Server returned ${res.status}: ${res.statusText}`,
          );
        }
        return res.json() as Promise<AccountsResponse>;
      })
      .then((data) => {
        setResponse(data);
        setLoading(false);
      })
      .catch((err: Error) => {
        if (err.name === "AbortError") {
          return; // Ignore aborted requests
        }
        setError(err.message || "Failed to retrieve archive accounts");
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchAccounts();

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [selectedChapter, selectedStatus, debouncedSearch, currentPage]);

  const handleClearAllFilters = () => {
    setSelectedChapter("ALL");
    setSelectedStatus("ALL");
    setSearchInput("");
    setDebouncedSearch("");
    setCurrentPage(1);
  };

  const hasActiveFilters =
    selectedChapter !== "ALL" || selectedStatus !== "ALL" || debouncedSearch !== "";

  const accounts = response?.data || [];
  const pagination = response?.pagination || { page: 1, limit: 12, total: 0, totalPages: 0 };

  const startRecord = pagination.total === 0 ? 0 : (pagination.page - 1) * pagination.limit + 1;
  const endRecord = Math.min(pagination.page * pagination.limit, pagination.total);

  return (
    <div
      className="animate-fade-in"
      style={{ maxWidth: "1340px", margin: "40px auto 80px", padding: "0 clamp(16px, 3vw, 32px)" }}
    >
      {/* 1. Header Section */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-end",
          marginBottom: "32px",
          borderBottom: "1px solid rgba(197, 160, 89, 0.3)",
          paddingBottom: "22px",
          flexWrap: "wrap",
          gap: "16px",
        }}
      >
        <div>
          <div
            className="eyebrow"
            style={{ color: "var(--gold)", letterSpacing: "0.22em", marginBottom: "6px" }}
          >
            ✦ DÍA DE LOS MUERTOS MACHINE IDENTITY ARCHIVE ✦
          </div>
          <h1
            className="display"
            style={{
              fontSize: "clamp(26px, 3.8vw, 40px)",
              color: "#f7ebd2",
              margin: "4px 0 8px",
              letterSpacing: "0.04em",
              textShadow: "0 2px 14px rgba(0, 0, 0, 0.8)",
            }}
          >
            The Four-Chamber Registry
          </h1>
          <p
            className="serif"
            style={{
              fontSize: "17px",
              color: "#c7b591",
              maxWidth: "680px",
              margin: 0,
              fontStyle: "italic",
            }}
          >
            Examine unmanaged deploy keys, orphaned service accounts, and silent machine tokens.
            Every claim is linked to source commit or ticket records.
          </p>
        </div>

        {/* Legend */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "12px",
            background: "rgba(13, 11, 15, 0.7)",
            border: "1px solid rgba(197, 160, 89, 0.2)",
            borderRadius: "4px",
            padding: "8px 14px",
          }}
        >
          <img
            src="/candleon.png"
            alt="Lit Candle"
            className="candle-glow"
            style={{ width: "20px", height: "36px", objectFit: "contain" }}
          />
          <div style={{ fontSize: "11px", color: "var(--muted)", maxWidth: "180px", lineHeight: 1.4 }}>
            <span style={{ color: "var(--gold2)", fontWeight: 600 }}>Kindled Flame:</span> Verified
            citation evidence recorded in active registry.
          </div>
        </div>
      </div>

      {/* 2. Filter & Search Control Panel */}
      <div
        className="panel"
        style={{
          padding: "20px 24px",
          marginBottom: "24px",
          display: "flex",
          gap: "16px",
          flexWrap: "wrap",
          alignItems: "center",
          justifyContent: "space-between",
          border: "1px solid var(--gold)",
          background:
            "linear-gradient(180deg, rgba(24, 20, 27, 0.96) 0%, rgba(13, 11, 15, 0.98) 100%)",
        }}
      >
        {/* Search Bar */}
        <div style={{ flex: "1 1 300px", position: "relative" }}>
          <input
            id="archive-search-input"
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Search by account ID, engineer name, tag (#legacy), or quote..."
            aria-label="Search machine identities"
            style={{
              width: "100%",
              padding: "11px 36px 11px 14px",
              background: "rgba(10, 8, 12, 0.85)",
              border: "1px solid var(--line)",
              borderRadius: "3px",
              color: "#f6e8c7",
              fontFamily: "var(--mono)",
              fontSize: "12.5px",
              boxShadow: "inset 0 2px 6px rgba(0, 0, 0, 0.6)",
            }}
          />
          {searchInput && (
            <button
              type="button"
              onClick={() => setSearchInput("")}
              aria-label="Clear search text"
              style={{
                position: "absolute",
                right: "10px",
                top: "50%",
                transform: "translateY(-50%)",
                background: "transparent",
                border: "none",
                color: "var(--gold2)",
                cursor: "pointer",
                fontSize: "14px",
              }}
            >
              ✕
            </button>
          )}
        </div>

        {/* Four Chamber Navigation Buttons */}
        <div
          role="group"
          aria-label="Filter by archive chamber"
          style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}
        >
          {["ALL", "LOST", "FORGOTTEN", "LONELY", "INNOCENT"].map((ch) => {
            const isActive = selectedChapter === ch;
            return (
              <button
                key={ch}
                id={`btn-chapter-${ch.toLowerCase()}`}
                type="button"
                onClick={() => handleChapterChange(ch)}
                className="btn small"
                style={{
                  background: isActive
                    ? "linear-gradient(180deg, #8b1e2d, #521019)"
                    : "rgba(22, 18, 24, 0.8)",
                  borderColor: isActive ? "var(--gold)" : "rgba(197, 160, 89, 0.25)",
                  color: isActive ? "#ffffff" : "#c7b591",
                  boxShadow: isActive ? "0 0 12px rgba(139, 30, 45, 0.4)" : "none",
                  fontSize: "10.5px",
                  letterSpacing: "0.08em",
                }}
              >
                {ch}
              </button>
            );
          })}
        </div>

        {/* Evidence Status Dropdown */}
        <div>
          <select
            id="archive-status-select"
            value={selectedStatus}
            onChange={(e) => handleStatusChange(e.target.value)}
            aria-label="Filter by evidence status"
            style={{
              padding: "10px 14px",
              background: "rgba(13, 11, 15, 0.9)",
              border: "1px solid var(--line)",
              borderRadius: "3px",
              color: "#f6e8c7",
              fontFamily: "var(--display)",
              fontSize: "11px",
              letterSpacing: "0.06em",
              cursor: "pointer",
            }}
          >
            <option value="ALL">ALL EVIDENCE STATUSES</option>
            <option value="verified">VERIFIED EVIDENCE ONLY</option>
            <option value="supported">SUPPORTED ONLY</option>
            <option value="conflicting">CONFLICTING CITATIONS</option>
            <option value="no_evidence">NO EVIDENCE (ORPHANED)</option>
          </select>
        </div>
      </div>

      {/* 3. Active Filters Summary Bar */}
      {hasActiveFilters && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            flexWrap: "wrap",
            marginBottom: "20px",
            fontSize: "12px",
            fontFamily: "var(--mono)",
            color: "#a99b82",
          }}
        >
          <span>ACTIVE FILTERS:</span>
          {selectedChapter !== "ALL" && (
            <span
              className="tag red"
              style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
            >
              Chapter: {selectedChapter}
              <button
                type="button"
                onClick={() => handleChapterChange("ALL")}
                aria-label="Remove chapter filter"
                style={{ background: "none", border: "none", color: "inherit", cursor: "pointer", padding: 0 }}
              >
                ✕
              </button>
            </span>
          )}
          {selectedStatus !== "ALL" && (
            <span
              className="tag gold"
              style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
            >
              Status: {selectedStatus}
              <button
                type="button"
                onClick={() => handleStatusChange("ALL")}
                aria-label="Remove status filter"
                style={{ background: "none", border: "none", color: "inherit", cursor: "pointer", padding: 0 }}
              >
                ✕
              </button>
            </span>
          )}
          {debouncedSearch && (
            <span
              className="tag gray"
              style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
            >
              Query: &ldquo;{debouncedSearch}&rdquo;
              <button
                type="button"
                onClick={() => setSearchInput("")}
                aria-label="Remove search query"
                style={{ background: "none", border: "none", color: "inherit", cursor: "pointer", padding: 0 }}
              >
                ✕
              </button>
            </span>
          )}
          <button
            type="button"
            onClick={handleClearAllFilters}
            id="btn-clear-all-filters"
            style={{
              background: "none",
              border: "none",
              color: "var(--gold2)",
              cursor: "pointer",
              textDecoration: "underline",
              fontSize: "11px",
              marginLeft: "6px",
            }}
          >
            Clear All Filters
          </button>
        </div>
      )}

      {/* 4. Main Content Area */}

      {/* Loading Skeleton State */}
      {loading && !response && (
        <div
          role="status"
          aria-live="polite"
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(320px, 1fr))",
            gap: "24px",
          }}
        >
          {Array.from({ length: 6 }).map((_, idx) => (
            <div
              key={idx}
              className="panel"
              style={{
                height: "280px",
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
                padding: "24px",
                border: "1px solid rgba(197, 160, 89, 0.2)",
                opacity: 0.6,
                animation: "pulse 1.5s ease-in-out infinite",
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <div style={{ width: "60px", height: "20px", background: "rgba(255,255,255,0.06)", borderRadius: "3px" }} />
                <div style={{ width: "80px", height: "20px", background: "rgba(255,255,255,0.06)", borderRadius: "3px" }} />
              </div>
              <div style={{ width: "85%", height: "22px", background: "rgba(197, 160, 89, 0.15)", borderRadius: "3px" }} />
              <div style={{ width: "100%", height: "60px", background: "rgba(255,255,255,0.04)", borderRadius: "3px" }} />
              <div style={{ width: "100%", height: "36px", background: "rgba(255,255,255,0.06)", borderRadius: "3px" }} />
            </div>
          ))}
        </div>
      )}

      {/* Error State */}
      {error && (
        <div
          role="alert"
          className="panel"
          style={{
            padding: "40px",
            textAlign: "center",
            border: "1px solid var(--crimson2)",
            background: "rgba(139, 30, 45, 0.15)",
          }}
        >
          <div style={{ fontSize: "28px", color: "var(--crimson2)", marginBottom: "12px" }}>⚠</div>
          <h2 className="display" style={{ fontSize: "20px", color: "#f7ebd2", margin: "0 0 10px" }}>
            Failed to Inquire the Archive Ledger
          </h2>
          <p style={{ color: "#e8c5be", maxWidth: "520px", margin: "0 auto 20px", fontSize: "14px" }}>
            {error}
          </p>
          <button
            type="button"
            onClick={fetchAccounts}
            className="btn small"
            id="btn-retry-archive"
            style={{ padding: "10px 24px" }}
          >
            ✦ Retry Querying Ledger
          </button>
        </div>
      )}

      {/* Empty State */}
      {!loading && !error && accounts.length === 0 && (
        <div
          className="panel"
          style={{
            padding: "54px 30px",
            textAlign: "center",
            border: "1px dashed rgba(197, 160, 89, 0.35)",
            background: "rgba(13, 11, 15, 0.8)",
          }}
        >
          <img
            src="/candleoff.png"
            alt="Unlit Candle"
            style={{ width: "42px", height: "68px", margin: "0 auto 18px", objectFit: "contain", opacity: 0.7 }}
          />
          <h2 className="display" style={{ fontSize: "22px", color: "var(--gold2)", margin: "0 0 8px" }}>
            No Machine Identities Found
          </h2>
          <p
            className="serif"
            style={{
              color: "#c7b591",
              maxWidth: "520px",
              margin: "0 auto 22px",
              fontSize: "16px",
              lineHeight: 1.5,
              fontStyle: "italic",
            }}
          >
            No records in the active synthetic audit bundle match your filter criteria or search query.
          </p>
          <button
            type="button"
            onClick={handleClearAllFilters}
            className="btn ghost small"
            id="btn-empty-clear-filters"
          >
            Reset Filters & View All Chambers
          </button>
        </div>
      )}

      {/* Populated Cards Grid */}
      {!loading && !error && accounts.length > 0 && (
        <>
          {/* Results Counter Header */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "16px",
              fontSize: "12px",
              fontFamily: "var(--mono)",
              color: "#a99b82",
            }}
          >
            <div>
              SHOWING {startRecord}–{endRecord} OF {pagination.total} MACHINE IDENTITIES
            </div>
            {pagination.totalPages > 1 && (
              <div>
                PAGE {pagination.page} OF {pagination.totalPages}
              </div>
            )}
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fill, minmax(320px, 1fr))",
              gap: "24px",
            }}
          >
            {accounts.map((acc: ArchiveAccount) => {
              const hasVerifiedQuote = acc.owner_status === "verified";
              return (
                <div
                  key={acc.account_id}
                  className="panel"
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "space-between",
                    padding: "24px",
                    border: "1px solid var(--line)",
                    position: "relative",
                    transition: "transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease",
                    background:
                      "linear-gradient(180deg, rgba(22, 18, 25, 0.95) 0%, rgba(13, 11, 15, 0.98) 100%)",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = "translateY(-3px)";
                    e.currentTarget.style.borderColor = "var(--gold)";
                    e.currentTarget.style.boxShadow = "0 12px 30px rgba(0, 0, 0, 0.8)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = "translateY(0)";
                    e.currentTarget.style.borderColor = "var(--line)";
                    e.currentTarget.style.boxShadow = "none";
                  }}
                >
                  <div>
                    {/* Top Row: Glyph & Candle Status, Chapter, Owner Status Tag */}
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "flex-start",
                        marginBottom: "14px",
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                        <img
                          src={hasVerifiedQuote ? "/candleon.png" : "/candleoff.png"}
                          alt={hasVerifiedQuote ? "Verified flame" : "Unverified key"}
                          className={hasVerifiedQuote ? "candle-glow" : undefined}
                          style={{ width: "20px", height: "36px", objectFit: "contain" }}
                        />
                        <span className="tag red">{acc.ghost_type}</span>
                      </div>
                      <span
                        className={`tag ${
                          acc.owner_status === "verified"
                            ? "green"
                            : acc.owner_status === "supported"
                              ? "gold"
                              : acc.owner_status === "conflicting"
                                ? "red"
                                : "gray"
                        }`}
                      >
                        {acc.owner_status.toUpperCase().replace("_", " ")}
                      </span>
                    </div>

                    {/* Account Identifier */}
                    <h2
                      className="mono"
                      style={{
                        fontSize: "14.5px",
                        color: "#f6e4bd",
                        marginBottom: "6px",
                        wordBreak: "break-all",
                        fontWeight: 600,
                      }}
                    >
                      {acc.account_id}
                    </h2>

                    {/* Owner Attribution Line */}
                    <div
                      style={{
                        fontSize: "12px",
                        fontFamily: "var(--mono)",
                        color: acc.owner_name ? "#c7b591" : "#80735e",
                        marginBottom: "10px",
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                      }}
                    >
                      <span>{acc.owner_name ? "👤" : "○"}</span>
                      <span>
                        {acc.owner_name ? `Owner: ${acc.owner_name}` : "Unregistered Owner (No Evidence)"}
                      </span>
                    </div>

                    {/* Kind and Tag Badges */}
                    <div
                      style={{
                        display: "flex",
                        gap: "6px",
                        flexWrap: "wrap",
                        marginBottom: "14px",
                      }}
                    >
                      <span className="tag gray">{acc.kind}</span>
                      {acc.tags.map((tag, tidx) => (
                        <span key={tidx} className="tag gray" style={{ fontSize: "9px" }}>
                          #{tag}
                        </span>
                      ))}
                    </div>

                    {/* Purpose Summary */}
                    {acc.purpose && (
                      <div
                        style={{
                          fontSize: "12px",
                          color: "#d0bd98",
                          lineHeight: 1.45,
                          marginBottom: "12px",
                        }}
                      >
                        {acc.purpose}
                      </div>
                    )}

                    {/* Evidence Quote Preview */}
                    <div
                      style={{
                        padding: "10px 12px",
                        background: "rgba(10, 8, 12, 0.7)",
                        borderLeft: "3px solid var(--gold)",
                        borderRadius: "0 3px 3px 0",
                        fontSize: "12px",
                        fontStyle: "italic",
                        color: "#ebd6b0",
                        lineHeight: 1.45,
                        marginBottom: "18px",
                      }}
                    >
                      &ldquo;{acc.primary_quote}&rdquo;
                    </div>
                  </div>

                  {/* Card Footer: Navigate to Case Dossier */}
                  <div
                    style={{
                      borderTop: "1px solid rgba(197, 160, 89, 0.2)",
                      paddingTop: "14px",
                    }}
                  >
                    <button
                      type="button"
                      id={`btn-case-${acc.account_id}`}
                      onClick={() => onRouteChange("case", { caseId: acc.case_id })}
                      className="btn secondary small"
                      style={{
                        width: "100%",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        fontSize: "11px",
                        letterSpacing: "0.06em",
                      }}
                    >
                      <span>Examine Tombstone Dossier</span>
                      <span>→</span>
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          {/* 5. Pagination Controls */}
          {pagination.totalPages > 1 && (
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                gap: "8px",
                marginTop: "40px",
                flexWrap: "wrap",
              }}
            >
              <button
                type="button"
                id="btn-archive-prev"
                onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
                disabled={pagination.page <= 1}
                className="btn ghost small"
                style={{ fontSize: "11px", opacity: pagination.page <= 1 ? 0.4 : 1 }}
              >
                ← Previous Page
              </button>

              {Array.from({ length: pagination.totalPages }).map((_, pIdx) => {
                const pageNumber = pIdx + 1;
                const isCurrent = pageNumber === pagination.page;
                return (
                  <button
                    key={pageNumber}
                    type="button"
                    onClick={() => setCurrentPage(pageNumber)}
                    className="btn small"
                    style={{
                      minWidth: "36px",
                      height: "36px",
                      padding: "0 8px",
                      fontSize: "11px",
                      fontFamily: "var(--mono)",
                      background: isCurrent ? "var(--gold)" : "rgba(22, 18, 24, 0.8)",
                      color: isCurrent ? "#120e14" : "#c7b591",
                      borderColor: isCurrent ? "var(--gold)" : "rgba(197, 160, 89, 0.2)",
                      fontWeight: isCurrent ? 700 : 400,
                    }}
                  >
                    {pageNumber}
                  </button>
                );
              })}

              <button
                type="button"
                id="btn-archive-next"
                onClick={() => setCurrentPage((p) => Math.min(p + 1, pagination.totalPages))}
                disabled={pagination.page >= pagination.totalPages}
                className="btn ghost small"
                style={{
                  fontSize: "11px",
                  opacity: pagination.page >= pagination.totalPages ? 0.4 : 1,
                }}
              >
                Next Page →
              </button>
            </div>
          )}
        </>
      )}

      {/* 6. Synthetic Data Trust Disclosure */}
      <div
        style={{
          marginTop: "60px",
          padding: "16px 20px",
          borderTop: "1px solid rgba(197, 160, 89, 0.15)",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: "12px",
          fontSize: "11px",
          fontFamily: "var(--mono)",
          color: "#746957",
        }}
      >
        <div>
          ✦ SYNTHETIC DEMO ARCHIVE · All 40 machine identities and commit quotations are synthetic
          fixtures deterministically evaluated for demonstration purposes.
        </div>
        <div style={{ color: "#a99b82" }}>
          Repository Engine: In-Memory Synthetic Store (Atlas Pluggable)
        </div>
      </div>
    </div>
  );
};

