import { AuthPage } from "./pages/AuthPage.js";
import { SignUpPage } from "./pages/SignUpPage.js";
import { FreeSpiritPage } from "./pages/FreeSpiritPage.js";
import { ArchivePage } from "./pages/ArchivePage.js";
import { CasePage } from "./pages/CasePage.js";

export function formatOwnerStatus(status: OwnerStatus): { label: string; icon: string } {
  switch (status) {
    case "verified":
      return { label: "Verified", icon: "✓" };
    case "supported":
      return { label: "Supported", icon: "▲" };
    case "conflicting":
      return { label: "Conflicting", icon: "⚠" };
    case "no_evidence":
      return { label: "No Evidence", icon: "○" };
  }
}

// Helper for initial route and caseId from hash
function parseHashRoute(): { route: string; caseId?: string } {
  if (typeof window !== "undefined" && window.location.hash) {
    const raw = window.location.hash.replace(/^#\/?/, "");
    const parts = raw.split("?")[0].split("/");
    const base = parts[0];
    const caseId = parts[1];
    if (base === "case" && caseId) {
      return { route: "case", caseId };
    }
    if (base) return { route: base };
  }
  return { route: "landing" };
}

export const App: React.FC = () => {
  const initial = parseHashRoute();
  const [currentRoute, setCurrentRoute] = useState<string>(initial.route);
  const [activeCaseId, setActiveCaseId] = useState<string>(
    initial.caseId || "case_demo_01",
  );
  const [demoModalOpen, setDemoModalOpen] = useState<boolean>(false);

  // Sync hash changes with state
  useEffect(() => {
    const handleHashChange = () => {
