    >
      {/* 1. Global Navigation TopBar */}
      <TopBar
        currentRoute={currentRoute}
        onRouteChange={handleNavigate}
        onOpenDemoModal={() => setDemoModalOpen(true)}
      />

      {/* 2. Page Content View */}
      <main style={{ flex: 1 }}>
        {currentRoute === "landing" || currentRoute === "" ? (
          <LandingPage onRouteChange={handleNavigate} onOpenDemo={() => setDemoModalOpen(true)} />
        ) : currentRoute === "auth" || currentRoute === "signin" ? (
          <AuthPage onRouteChange={handleNavigate} onOpenDemoModal={() => setDemoModalOpen(true)} />
        ) : currentRoute === "spirit" ? (
          <FreeSpiritPage onRouteChange={handleNavigate} />
        ) : currentRoute === "signup" ? (
          <SignUpPage
            onRouteChange={handleNavigate}
            onOpenDemoModal={() => setDemoModalOpen(true)}
          />

