const http = require('http');

const urls = [
  'http://localhost:3000/',
  'http://localhost:3000/api/accounts?chapter=LOST&limit=3',
  'http://localhost:3001/api/accounts?chapter=INNOCENT&limit=3',
  'http://localhost:3001/healthz'
];

let pending = urls.length;

urls.forEach(url => {
  http.get(url, res => {
    console.log(`${res.statusCode} OK: ${url}`);
    pending--;
    if (pending === 0) process.exit(0);
  }).on('error', err => {
    console.error(`ERROR: ${url} -> ${err.message}`);
    pending--;
    if (pending === 0) process.exit(1);
  });
});

