9:  * Splits text into highlighted segments matching target quote.
10:  * Never uses dangerouslySetInnerHTML; produces pure React string nodes.
11:  */
12: export function highlightQuote(content: string, quote: string): HighlightSegment[] {
13:   if (!content || !quote || quote.trim().length === 0) {
14:     return [{ text: content, isMatch: false }];
15:   }
16: 
17:   const lowerContent = content.toLowerCase();
18:   const lowerQuote = quote.toLowerCase().trim();
19: 
20:   const matchIdx = lowerContent.indexOf(lowerQuote);
21:   if (matchIdx === -1) {
22:     return [{ text: content, isMatch: false }];
23:   }
24: 
25:   const before = content.slice(0, matchIdx);
26:   const match = content.slice(matchIdx, matchIdx + lowerQuote.length);
27:   const after = content.slice(matchIdx + lowerQuote.length);
28: 
29:   const segments: HighlightSegment[] = [];
30:   if (before) segments.push({ text: before, isMatch: false });
31:   segments.push({ text: match, isMatch: true });
32:   if (after) segments.push({ text: after, isMatch: false });
33: 
34:   return segments;
35: }
