const http = require('http');

function testEndpoint(path) {
  return new Promise((resolve) => {
    http.get('http://localhost:3000' + path, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        console.log(`STATUS: ${res.statusCode} | PATH: ${path} | SAMPLE: ${data.slice(0, 80)}...`);
        resolve();
      });
    }).on('error', err => {
      console.error(`ERROR: ${path} - ${err.message}`);
      resolve();
    });
  });
}

(async () => {
  console.log('Testing live dev server endpoints at http://localhost:3000:');
  await testEndpoint('/api/cases/case_demo_01');
  await testEndpoint('/api/cases/case_demo_01/records');
  await testEndpoint('/api/records/rec_commit_4021');
  await testEndpoint('/api/cases/case_nonexistent');
  await testEndpoint('/api/records/rec_nonexistent');
})();

