                        }`}
                      >
                        {inv.status.toUpperCase().replace("_", " ")}
                      </span>
                    </td>
                    <td
                      style={{
                        padding: "14px 10px",
                        fontFamily: "var(--mono)",
                        color: "var(--paper)",
                      }}
                    >
                      {inv.file_count}
                    </td>
                    <td
                      style={{
                        padding: "14px 10px",
                        fontFamily: "var(--mono)",
                        color: "var(--paper)",
                      }}
                    >
                      {inv.record_count}
                    </td>
                    <td
                      style={{
                        padding: "14px 10px",
                        fontFamily: "var(--mono)",
                        color: "var(--gold2)",
                        fontWeight: 600,
                      }}
                    >
                      {inv.accounts_discovered_count}
                    </td>
                    <td style={{ padding: "14px 10px", textAlign: "right" }}>
                      <button
                        type="button"
                        id={`btn-inspect-inv-${inv.investigation_id}`}
                        onClick={() =>
                          onRouteChange("investigation", { id: inv.investigation_id })
                        }
                        className="btn secondary small"
                        style={{ fontSize: "10.5px" }}
                      >
                        Inspect Findings →
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from "react";
import {
  CreateInvestigationSchema,
  Investigation,
  InvestigationFindings,
  SingleFileInput,
} from "@keys/contracts";

export interface NewInvestigationPageProps {
  investigationId?: string;
  onRouteChange: (route: string, params?: Record<string, string>) => void;
}

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const ALLOWED_EXTS = [".json", ".jsonl", ".ndjson", ".log", ".txt"];

export const NewInvestigationPage: React.FC<NewInvestigationPageProps> = ({
  investigationId: initialInvId,
  onRouteChange,
}) => {
  // Wizard state: "create" -> "upload" -> "processing" -> "results"
  const [currentStep, setCurrentStep] = useState<"create" | "upload" | "processing" | "results">(
    initialInvId ? "results" : "create",
  );

  // Form State
  const [name, setName] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [formErrors, setFormErrors] = useState<{ name?: string; description?: string }>({});

  // Active Investigation
  const [investigation, setInvestigation] = useState<Investigation | null>(null);
  const [findings, setFindings] = useState<InvestigationFindings | null>(null);

  // File Upload State
  const [selectedFiles, setSelectedFiles] = useState<Array<{ file: File; id: string }>>([]);
  const [rejectedFiles, setRejectedFiles] = useState<Array<{ name: string; reason: string }>>([]);
  const [uploadProgress, setUploadProgress] = useState<number>(0);
  const [uploading, setUploading] = useState<boolean>(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [processingError, setProcessingError] = useState<string | null>(null);
  const [isDragOver, setIsDragOver] = useState<boolean>(false);

  const fileInputRef = useRef<HTMLInputElement | null>(null);

  // If opened with an existing investigation ID, load its findings directly
  useEffect(() => {
    if (initialInvId) {
      fetch(`/api/investigations/${encodeURIComponent(initialInvId)}/findings`)
        .then(async (res) => {
          if (!res.ok) {
            // If not processed yet, try retrieving the investigation metadata
            return fetch(`/api/investigations/${encodeURIComponent(initialInvId)}`)
              .then(async (invRes) => {
                if (!invRes.ok) throw new Error("Investigation not found");
                return invRes.json() as Promise<Investigation>;
              })
              .then((inv) => {
                setInvestigation(inv);
                setCurrentStep(inv.status === "completed" ? "results" : "upload");
              });
          }
          return (res.json() as Promise<InvestigationFindings>).then((data) => {
            setFindings(data);
            setInvestigation(data.investigation);
            setCurrentStep("results");
          });
        })
        .catch((err: Error) => {
          setProcessingError(err.message || "Failed to load investigation");
        });
    }
  }, [initialInvId]);

  // Step 1: Create Investigation
  const handleCreateInvestigation = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormErrors({});

    const parseResult = CreateInvestigationSchema.safeParse({ name, description });
    if (!parseResult.success) {
      const fieldErrors: { name?: string; description?: string } = {};
      parseResult.error.issues.forEach((issue) => {
        if (issue.path[0] === "name") fieldErrors.name = issue.message;
        if (issue.path[0] === "description") fieldErrors.description = issue.message;
      });
      setFormErrors(fieldErrors);
      return;
    }

    try {
      setUploading(true);
      const res = await fetch("/api/investigations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parseResult.data),
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || "Failed to create investigation");
      }

      const created = (await res.json()) as Investigation;
      setInvestigation(created);
      setCurrentStep("upload");
      setUploading(false);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Creation failed";
      setUploadError(msg);
      setUploading(false);
    }
  };

  // Step 2: Validate and select files
  const handleFilesAdded = (files: FileList | null) => {
    if (!files) return;
    setUploadError(null);

    const newAccepted: Array<{ file: File; id: string }> = [];
    const newRejected: Array<{ name: string; reason: string }> = [];

    Array.from(files).forEach((f) => {
      const ext = "." + f.name.split(".").pop()?.toLowerCase();

      if (!ALLOWED_EXTS.includes(ext)) {
        newRejected.push({
          name: f.name,
          reason: `Unsupported format (${ext}). Allowed: .json, .jsonl, .ndjson, .log, .txt`,
        });
        return;
      }

      if (f.size === 0) {
        newRejected.push({
          name: f.name,
          reason: "File is empty (0 bytes).",
        });
        return;
      }

      if (f.size > MAX_FILE_SIZE) {
        newRejected.push({
          name: f.name,
          reason: `File size (${(f.size / (1024 * 1024)).toFixed(2)} MB) exceeds 5MB limit.`,
        });
        return;
      }

      // Check duplicate in current selection
      const isDuplicate = selectedFiles.some((item) => item.file.name === f.name);
      if (isDuplicate) {
        newRejected.push({
          name: f.name,
          reason: "File already selected.",
        });
        return;
      }

      newAccepted.push({
        file: f,
        id: `${f.name}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      });
    });

    setSelectedFiles((prev) => [...prev, ...newAccepted]);
    if (newRejected.length > 0) {
      setRejectedFiles((prev) => [...prev, ...newRejected]);
    }
  };

  const handleRemoveFile = (id: string) => {
    setSelectedFiles((prev) => prev.filter((item) => item.id !== id));
  };

  const handleClearRejected = () => {
    setRejectedFiles([]);
  };

  // Helper: Load standard sample audit files for quick evaluation
  const handleLoadSampleLogs = () => {
    const sampleCommit = new File(
      [
        `commit 8f92ab018442bc014aef72948c21a4f00123\nAuthor: Carlos Mendez <cmendez@internal.corp>\nDate: Sat Apr 12 10:15:30 2025 -0400\n\n    Add staging deploy key acc_deploy_key_881 for automated night-build pipeline.\n    Signed-off-by: Carlos Mendez <cmendez@internal.corp>\n`,
      ],
      "staging-commits.log",
      { type: "text/plain" },
    );

    const sampleTicket = new File(
      [
        JSON.stringify(
          [
            {
              record_id: "rec_ticket_1092",
              type: "ticket",
              ts: "2025-04-10T14:22:00.000Z",
              author_handle: "cmendez",
              actor_account_id: "acc_deploy_key_881",
              content:
                "TICKET-1092 [INFRA]: Automated night-build deployment pipeline key for staging cluster. Expiration: 90 days.",
              structured: true,
            },
            {
              record_id: "rec_log_909",
              type: "deploy_log",
              ts: "2024-11-03T08:15:00.000Z",
              actor_account_id: "acc_service_runner_404",
              content:
                "[SYSTEM DAEMON] Automated sync runner deployed with unmanaged token rotation for acc_service_runner_404.",
              structured: false,
            },
          ],
          null,
          2,
        ),
      ],
      "infra-audit.json",
      { type: "application/json" },
    );

    handleFilesAdded([sampleCommit, sampleTicket] as unknown as FileList);
  };

  // Step 3: Upload files and trigger processing
  const handleUploadAndProcess = async () => {
    if (!investigation) return;
    if (selectedFiles.length === 0) {
      setUploadError("Please select at least one valid evidence file to upload.");
      return;
    }

    setUploading(true);
    setUploadError(null);
    setUploadProgress(15);

    try {
      // Read all selected files as text
      const filesPayload: SingleFileInput[] = await Promise.all(
        selectedFiles.map(async ({ file }) => {
          const content = await file.text();
          return {
            filename: file.name,
            content,
            size_bytes: file.size,
          };
        }),
      );

      setUploadProgress(45);

      // 1. Submit files to backend
      const uploadRes = await fetch(`/api/investigations/${investigation.investigation_id}/upload`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ files: filesPayload }),
      });

      if (!uploadRes.ok) {
        const body = (await uploadRes.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || `Upload failed: ${uploadRes.status}`);
      }

      setUploadProgress(75);
      setCurrentStep("processing");

      // 2. Trigger deterministic processing & case matching
      const processRes = await fetch(
        `/api/investigations/${investigation.investigation_id}/process`,
        {
          method: "POST",
        },
      );

      if (!processRes.ok) {
        const body = (await processRes.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || `Processing failed: ${processRes.status}`);
      }

      const findingsData = (await processRes.json()) as InvestigationFindings;
      setUploadProgress(100);
      setFindings(findingsData);
      setInvestigation(findingsData.investigation);
      setCurrentStep("results");
      setUploading(false);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Upload processing failed";
      setUploadError(msg);
      setProcessingError(msg);
      setUploading(false);
      setCurrentStep("upload");
    }
  };

  return (
    <div
      className="animate-fade-in"
      style={{ maxWidth: "1240px", margin: "40px auto 80px", padding: "0 clamp(16px, 3vw, 28px)" }}
    >
      {/* Top Breadcrumb Navigation */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "24px",
          flexWrap: "wrap",
          gap: "12px",
        }}
      >
        <button
          type="button"
          id="btn-return-dashboard"
          onClick={() => onRouteChange("dashboard")}
          className="btn ghost small"
        >
          ← Return to Sanctuary Dashboard
        </button>

        <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
          {["create", "upload", "results"].map((step, idx) => (
            <span
              key={step}
              className={`tag ${
                currentStep === step ||
                (step === "create" && currentStep !== "create") ||
                (step === "upload" && currentStep === "results")
                  ? "gold"
                  : "gray"
              }`}
              style={{ fontSize: "10px" }}
            >
              {idx + 1}. {step.toUpperCase()}
            </span>
          ))}
        </div>
      </div>

      {/* ======================================================== */}
      {/* STEP 1: CREATE INVESTIGATION                             */}
      {/* ======================================================== */}
      {currentStep === "create" && (
        <div className="panel" style={{ padding: "40px", maxWidth: "680px", margin: "0 auto" }}>
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            STEP 1 · INITIATE INVESTIGATION AUDIT
          </div>
          <h1
            className="display"
            style={{ fontSize: "28px", color: "var(--cream)", margin: "0 0 12px" }}
          >
            Create New Investigation
          </h1>
          <p
            className="serif"
            style={{ fontSize: "16px", color: "#c7b591", fontStyle: "italic", marginBottom: "28px" }}
          >
            Define an investigation boundary to associate uploaded git commits, infrastructure
            tickets, and daemon logs with machine identity dossiers.
          </p>

          <form onSubmit={handleCreateInvestigation}>
            <div style={{ marginBottom: "20px" }}>
              <label
                htmlFor="inv-name"
                style={{
                  display: "block",
                  fontFamily: "var(--display)",
                  fontSize: "11px",
                  letterSpacing: "0.08em",
                  color: "var(--gold2)",
                  marginBottom: "8px",
                }}
              >
                INVESTIGATION NAME *
              </label>
              <input
                id="inv-name"
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. Staging Pipeline & Deploy Credentials Audit"
                style={{
                  width: "100%",
                  padding: "12px 14px",
                  background: "rgba(10, 8, 12, 0.8)",
                  border: formErrors.name
                    ? "1px solid var(--crimson2)"
                    : "1px solid rgba(197, 160, 89, 0.4)",
                  color: "#f7ebd2",
                  borderRadius: "3px",
                  fontSize: "14px",
                  fontFamily: "var(--sans)",
                }}
              />
              {formErrors.name && (
                <div style={{ color: "var(--crimson2)", fontSize: "12px", marginTop: "6px" }}>
                  {formErrors.name}
                </div>
              )}
            </div>

            <div style={{ marginBottom: "28px" }}>
              <label
                htmlFor="inv-desc"
                style={{
                  display: "block",
                  fontFamily: "var(--display)",
                  fontSize: "11px",
                  letterSpacing: "0.08em",
                  color: "var(--gold2)",
                  marginBottom: "8px",
                }}
              >
                DESCRIPTION (OPTIONAL)
              </label>
              <textarea
                id="inv-desc"
                rows={3}
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Operational scope, targeted clusters, or incident ticket references..."
                style={{
                  width: "100%",
                  padding: "12px 14px",
                  background: "rgba(10, 8, 12, 0.8)",
                  border: formErrors.description
                    ? "1px solid var(--crimson2)"
                    : "1px solid rgba(197, 160, 89, 0.4)",
                  color: "#f7ebd2",
                  borderRadius: "3px",
                  fontSize: "13px",
                  fontFamily: "var(--sans)",
                  resize: "vertical",
                }}
              />
              {formErrors.description && (
                <div style={{ color: "var(--crimson2)", fontSize: "12px", marginTop: "6px" }}>
                  {formErrors.description}
                </div>
              )}
            </div>

            {uploadError && (
              <div
                style={{
                  padding: "12px",
                  background: "rgba(109,23,27,0.3)",
                  border: "1px solid var(--crimson2)",
                  borderRadius: "3px",
                  fontSize: "12.5px",
                  color: "#f0b9ad",
                  marginBottom: "20px",
                }}
              >
                {uploadError}
              </div>
            )}

            <div style={{ display: "flex", justifyContent: "flex-end", gap: "12px" }}>
              <button
                type="button"
                onClick={() => onRouteChange("dashboard")}
                className="btn ghost small"
              >
                Cancel
              </button>
              <button
                type="submit"
                id="btn-submit-create-investigation"
                disabled={uploading}
                className="btn"
              >
                {uploading ? "Creating..." : "Create Investigation & Proceed →"}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 2: UPLOAD SOURCE RECORDS                            */}
      {/* ======================================================== */}
      {currentStep === "upload" && investigation && (
        <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
          {/* Header Card */}
          <div className="panel" style={{ padding: "28px" }}>
            <div className="eyebrow" style={{ color: "var(--gold)" }}>
              STEP 2 · INGEST ENGINEERING AUDIT RECORDS
            </div>
            <h2
              className="display"
              style={{ fontSize: "24px", color: "var(--cream)", margin: "4px 0 8px" }}
            >
              {investigation.name}
            </h2>
            <div
              className="mono"
              style={{ fontSize: "12px", color: "var(--muted)", marginBottom: "4px" }}
            >
              INVESTIGATION ID: {investigation.investigation_id} ✦ BUNDLE: {investigation.bundle_id}
            </div>
            {investigation.description && (
              <p style={{ fontSize: "13.5px", color: "#c7b591", margin: 0, fontStyle: "italic" }}>
                {investigation.description}
              </p>
            )}
          </div>

          {/* Drag & Drop Zone */}
          <div
            onDragOver={(e) => {
              e.preventDefault();
              setIsDragOver(true);
            }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={(e) => {
              e.preventDefault();
              setIsDragOver(false);
              handleFilesAdded(e.dataTransfer.files);
            }}
            style={{
              padding: "48px 24px",
              textAlign: "center",
              border: isDragOver ? "2px dashed var(--gold2)" : "2px dashed var(--line)",
              background: isDragOver ? "rgba(197, 160, 89, 0.12)" : "rgba(18, 14, 20, 0.8)",
              borderRadius: "4px",
              transition: "all 0.2s ease",
            }}
          >
            <img
              src="/goldenbook.png"
              alt="Intake Records"
              style={{
                width: "64px",
                height: "64px",
                objectFit: "contain",
                margin: "0 auto 14px",
                opacity: 0.9,
              }}
            />
            <h3
              className="display"
              style={{ fontSize: "19px", color: "var(--gold2)", margin: "0 0 8px" }}
            >
              Drag &amp; Drop Engineering Records Here
            </h3>
            <p style={{ fontSize: "13px", color: "var(--muted)", maxWidth: "480px", margin: "0 auto 16px" }}>
              Supported formats: <code>.json</code>, <code>.jsonl</code>, <code>.ndjson</code>,{" "}
              <code>.log</code>, <code>.txt</code> (Max 5MB per file).
            </p>

            <div style={{ display: "flex", gap: "12px", justifyContent: "center", flexWrap: "wrap" }}>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept=".json,.jsonl,.ndjson,.log,.txt"
                style={{ display: "none" }}
                onChange={(e) => handleFilesAdded(e.target.files)}
              />
              <button
                type="button"
                id="btn-browse-files"
                onClick={() => fileInputRef.current?.click()}
                className="btn small"
              >
                Browse Files
              </button>
              <button
                type="button"
                id="btn-load-sample-logs"
                onClick={handleLoadSampleLogs}
                className="btn secondary small"
              >
                + Load Sample Audit Logs
              </button>
            </div>
          </div>

          {/* Rejected Files Alert */}
          {rejectedFiles.length > 0 && (
            <div
              style={{
                padding: "16px 20px",
                background: "rgba(109,23,27,0.25)",
                border: "1px solid var(--crimson2)",
                borderRadius: "4px",
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "8px",
                }}
              >
                <strong style={{ color: "#f0b9ad", fontSize: "13px" }}>
                  Rejected Files ({rejectedFiles.length})
                </strong>
                <button
                  type="button"
                  onClick={handleClearRejected}
                  className="btn ghost small"
                  style={{ fontSize: "10px", padding: "2px 6px" }}
                >
                  Dismiss
                </button>
              </div>
              <ul style={{ margin: 0, paddingLeft: "18px", fontSize: "12px", color: "#e8c5be" }}>
                {rejectedFiles.map((rf, rfid) => (
                  <li key={rfid}>
                    <strong>{rf.name}</strong>: {rf.reason}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Selected Files List */}
          {selectedFiles.length > 0 && (
            <div className="panel" style={{ padding: "24px" }}>
              <div
                className="eyebrow"
                style={{ color: "var(--gold)", marginBottom: "14px" }}
              >
                ACCEPTED STAGED FILES ({selectedFiles.length})
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                {selectedFiles.map(({ file, id }) => (
                  <div
                    key={id}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      padding: "10px 14px",
                      background: "rgba(0,0,0,0.35)",
                      borderRadius: "3px",
                      borderLeft: "3px solid var(--gold)",
                    }}
                  >
                    <div>
                      <span className="mono" style={{ fontSize: "13px", color: "#f7ebd2" }}>
                        {file.name}
                      </span>
                      <span
                        className="mono"
                        style={{ fontSize: "11px", color: "var(--muted)", marginLeft: "12px" }}
                      >
                        ({(file.size / 1024).toFixed(1)} KB)
                      </span>
                    </div>
                    <button
                      type="button"
                      onClick={() => handleRemoveFile(id)}
                      className="btn ghost small"
                      style={{ fontSize: "10px", color: "var(--crimson2)" }}
                    >
                      Remove
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Progress Bar (if uploading) */}
          {uploading && (
            <div style={{ marginTop: "12px" }}>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  fontSize: "12px",
                  color: "var(--gold2)",
                  marginBottom: "6px",
                }}
              >
                <span>Ingesting and parsing records...</span>
                <span>{uploadProgress}%</span>
              </div>
              <div
                style={{
                  height: "6px",
                  background: "rgba(255,255,255,0.1)",
                  borderRadius: "3px",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${uploadProgress}%`,
                    background: "var(--gold)",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>
            </div>
          )}

          {uploadError && (
            <div
              style={{
                padding: "12px",
                background: "rgba(109,23,27,0.3)",
                border: "1px solid var(--crimson2)",
                borderRadius: "3px",
                fontSize: "12.5px",
                color: "#f0b9ad",
              }}
            >
              {uploadError}
            </div>
          )}

          {/* Action Row */}
          <div style={{ display: "flex", justifyContent: "flex-end", gap: "12px" }}>
            <button
              type="button"
              onClick={() => setCurrentStep("create")}
              className="btn ghost small"
            >
              ← Back to Details
            </button>
            <button
              type="button"
              id="btn-ingest-and-process"
              disabled={uploading || selectedFiles.length === 0}
              onClick={handleUploadAndProcess}
              className="btn"
              style={{
                background: "linear-gradient(180deg, #b02638, #69131f)",
                borderColor: "var(--gold2)",
              }}
            >
              {uploading ? "Ingesting & Verifying..." : "Ingest & Run Evidence Verification →"}
            </button>
          </div>
        </div>
      )}

      {/* ======================================================== */}
      {/* PROCESSING STATE SPINNER                                 */}
      {/* ======================================================== */}
      {currentStep === "processing" && (
        <div
          className="panel"
          style={{
            padding: "54px 30px",
            textAlign: "center",
            border: "1px dashed var(--gold)",
            background: "rgba(18, 14, 20, 0.95)",
          }}
        >
          <img
            src="/candleon.png"
            alt="Lighting Candle"
            className="candle-glow"
            style={{ width: "32px", height: "54px", margin: "0 auto 16px", objectFit: "contain" }}
          />
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            STAGE 5 · DETERMINISTIC VERIFICATION ACTIVE
          </div>
          <h2 className="display" style={{ fontSize: "22px", color: "var(--cream)", margin: "0 0 12px" }}>
            Verifying Audit Substrings &amp; Identity Provenance...
          </h2>
          <p
            className="serif"
            style={{ color: "#c7b591", fontStyle: "italic", maxWidth: "520px", margin: "0 auto" }}
          >
            Performing deterministic character normalization, personnel cross-referencing, and
            quarantining ungrounded claims with reason codes R1–R5.
          </p>
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 5: INVESTIGATION RESULTS                            */}
      {/* ======================================================== */}
      {currentStep === "results" && findings && (
        <div style={{ display: "flex", flexDirection: "column", gap: "28px" }}>
          {/* Header Card */}
          <div
            className="panel"
            style={{
              padding: "36px",
              border: "1px solid var(--gold)",
              backgroundImage: "linear-gradient(135deg, rgba(35,26,20,0.98), rgba(16,13,11,0.96))",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "flex-start",
                flexWrap: "wrap",
                gap: "20px",
              }}
            >
              <div>
                <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "6px" }}>
                  INVESTIGATION FINDINGS REPORT ✦ {findings.investigation.investigation_id}
                </div>
                <h1
                  className="display"
                  style={{ fontSize: "28px", color: "var(--cream)", margin: "4px 0 10px" }}
                >
                  {findings.investigation.name}
                </h1>
                <p style={{ fontSize: "14px", color: "#c7b591", margin: 0, fontStyle: "italic" }}>
                  {findings.investigation.description || "Ad-hoc machine identity audit investigation."}
                </p>
              </div>

              <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                <span className="tag green">STATUS: COMPLETED</span>
                <span className="tag gray">
                  RECORDS: {findings.processing_summary.total_records_processed}
                </span>
                <span className="tag gold">
                  KEYS DISCOVERED: {findings.discovered_accounts.length}
                </span>
              </div>
            </div>

            {/* AI Model & Pipeline Transparency Banner */}
            <div
              style={{
                marginTop: "24px",
                padding: "14px 18px",
                background: "rgba(0,0,0,0.4)",
                borderRadius: "3px",
                borderLeft: "3px solid var(--blue)",
                fontSize: "12.5px",
                color: "#d0bd98",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
                gap: "10px",
              }}
            >
              <div>
                <strong style={{ color: "#f0dfbd" }}>Deterministic Verification Engine:</strong>{" "}
                All citations checked verbatim against raw logs. Model-assisted inference is tagged as{" "}
                <code>{findings.processing_summary.model_extraction_status}</code> (no ungrounded
                claims accepted).
              </div>
              <span className="tag gray" style={{ fontSize: "10px" }}>
                CLAIMS VERIFIED: {findings.processing_summary.claims_verified_count} | QUARANTINED:{" "}
                {findings.processing_summary.claims_quarantined_count}
              </span>
            </div>
          </div>

          {/* Discovered Machine Identities Table */}
          <div className="panel" style={{ padding: "28px" }}>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "20px",
                flexWrap: "wrap",
                gap: "12px",
              }}
            >
              <div>
                <div className="eyebrow" style={{ color: "var(--gold)" }}>
                  DISCOVERED MACHINE IDENTITIES
                </div>
                <h3
                  className="display"
                  style={{ fontSize: "20px", color: "var(--cream)", margin: "4px 0 0" }}
                >
                  Associated Machine Accounts ({findings.discovered_accounts.length})
                </h3>
              </div>

              <button
                type="button"
                onClick={() => onRouteChange("archive")}
                className="btn ghost small"
              >
                View in Four-Chamber Registry →
              </button>
            </div>

            {findings.discovered_accounts.length === 0 ? (
              <div
                style={{
                  padding: "36px",
                  textAlign: "center",
                  border: "1px dashed var(--line)",
                  borderRadius: "4px",
                }}
              >
                <p style={{ color: "var(--muted)", margin: 0, fontStyle: "italic" }}>
                  No known machine identities were matched in the uploaded log content.
                </p>
              </div>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13px" }}>
                  <thead>
                    <tr
                      style={{
                        borderBottom: "1px solid var(--line)",
                        color: "var(--gold2)",
                        fontFamily: "var(--display)",
                        fontSize: "11px",
                        letterSpacing: "0.08em",
                        textAlign: "left",
                      }}
                    >
                      <th style={{ padding: "12px 10px" }}>ACCOUNT IDENTIFIER</th>
                      <th style={{ padding: "12px 10px" }}>KIND</th>
                      <th style={{ padding: "12px 10px" }}>CHAMBER</th>
                      <th style={{ padding: "12px 10px" }}>OWNER STATUS</th>
                      <th style={{ padding: "12px 10px" }}>PRIMARY CITATION</th>
                      <th style={{ padding: "12px 10px", textAlign: "right" }}>ACTION</th>
                    </tr>
                  </thead>
                  <tbody>
                    {findings.discovered_accounts.map((acc) => (
                      <tr
                        key={acc.account_id}
                        style={{
                          borderBottom: "1px solid rgba(201,157,83,0.12)",
                          transition: "background-color 0.2s",
                        }}
                      >
                        <td style={{ padding: "14px 10px", fontFamily: "var(--mono)", color: "#f6e4bd" }}>
                          {acc.account_id}
                        </td>
                        <td style={{ padding: "14px 10px" }}>
                          <span className="tag gray">{acc.kind}</span>
                        </td>
                        <td style={{ padding: "14px 10px" }}>
                          <span className="tag red">{acc.ghost_type}</span>
                        </td>
                        <td style={{ padding: "14px 10px" }}>
                          <span
                            className={`tag ${
                              acc.owner_status === "verified"
                                ? "green"
                                : acc.owner_status === "supported"
                                  ? "gold"
                                  : acc.owner_status === "conflicting"
                                    ? "red"
                                    : "gray"
                            }`}
                          >
                            {acc.owner_status.toUpperCase()}
                          </span>
                        </td>
                        <td style={{ padding: "14px 10px", maxWidth: "340px", fontStyle: "italic", color: "#ebd6b0" }}>
                          &ldquo;{acc.primary_quote}&rdquo;
                        </td>
                        <td style={{ padding: "14px 10px", textAlign: "right" }}>
                          <button
                            type="button"
                            id={`btn-dossier-${acc.account_id}`}
                            onClick={() => onRouteChange("case", { caseId: acc.case_id })}
                            className="btn small"
                            style={{ fontSize: "10px" }}
                          >
                            Examine Dossier →
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Accepted Claims vs Quarantined Claims Grid */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
              gap: "24px",
            }}
          >
            {/* Accepted Claims */}
            <div className="panel" style={{ padding: "28px" }}>
              <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "12px" }}>
                DETERMINISTICALLY VERIFIED CITATIONS
              </div>
              <h3 className="display" style={{ fontSize: "18px", color: "var(--cream)", margin: "0 0 16px" }}>
                Accepted Claims ({findings.processing_summary.claims_verified_count})
              </h3>

              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                {findings.cases.flatMap((c) => c.claims_accepted).slice(0, 5).map((cl, idx) => (
                  <div
                    key={idx}
                    style={{
                      padding: "12px 14px",
                      background: "rgba(0,0,0,0.35)",
                      borderRadius: "3px",
                      borderLeft: "3px solid var(--gold)",
                    }}
                  >
                    <div style={{ display: "flex", gap: "8px", alignItems: "center", marginBottom: "4px" }}>
                      <span className="tag red" style={{ fontSize: "9px" }}>
                        [{cl.kind.toUpperCase()}]
                      </span>
                      <span className="mono" style={{ fontSize: "10px", color: "var(--gold)" }}>
                        REF: {cl.record_id}
                      </span>
                    </div>
                    <div style={{ fontSize: "13px", color: "#f1dfb8", marginBottom: "6px" }}>
                      {cl.text}
                    </div>
                    <div
                      className="mono"
                      style={{
                        fontSize: "11px",
                        color: "var(--gold2)",
                        background: "rgba(0,0,0,0.4)",
                        padding: "6px 8px",
                        borderRadius: "2px",
                      }}
                    >
                      &ldquo;{cl.quote}&rdquo;
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Quarantined Claims (R1–R5) */}
            <div className="panel" style={{ padding: "28px" }}>
              <div className="eyebrow" style={{ color: "var(--crimson2)", marginBottom: "12px" }}>
                GUARDRAIL QUARANTINE (REASON CODES R1–R5)
              </div>
              <h3 className="display" style={{ fontSize: "18px", color: "#f6e4bd", margin: "0 0 16px" }}>
                Removed / Quarantined Assertions ({findings.processing_summary.claims_quarantined_count})
              </h3>

              <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                {findings.cases.flatMap((c) => c.claims_removed).slice(0, 5).map((rem, idx) => (
                  <div
                    key={idx}
                    style={{
                      padding: "12px 14px",
                      background: "rgba(35, 15, 18, 0.7)",
                      borderRadius: "3px",
                      borderLeft: "3px solid var(--crimson2)",
                    }}
                  >
                    <div style={{ display: "flex", gap: "8px", alignItems: "center", marginBottom: "4px" }}>
                      <span className="tag red" style={{ fontSize: "9px" }}>
                        REASON: {rem.reason_code}
                      </span>
                      <span className="mono" style={{ fontSize: "10px", color: "var(--muted)" }}>
                        CLAIM: {rem.kind.toUpperCase()}
                      </span>
                    </div>
                    <div style={{ fontSize: "13px", color: "#f6e4bd", marginBottom: "6px" }}>
                      {rem.text}
                    </div>
                    <div
                      className="mono"
                      style={{
                        fontSize: "11px",
                        color: "#e07a5f",
                        background: "rgba(0,0,0,0.5)",
                        padding: "6px 8px",
                        borderRadius: "2px",
                      }}
                    >
                      Rejected: &ldquo;{rem.quote}&rdquo;
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Footer Actions */}
          <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: "12px" }}>
            <button
              type="button"
              onClick={() => onRouteChange("dashboard")}
              className="btn secondary small"
            >
              ← Back to Sanctuary Dashboard
            </button>

            <button
              type="button"
              onClick={() => {
                setInvestigation(null);
                setFindings(null);
                setSelectedFiles([]);
                setCurrentStep("create");
              }}
              className="btn small"
            >
              + Create Another Investigation
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

