import React, { useState, useEffect } from "react";
import { OwnerStatus } from "@keys/contracts";
import { TopBar } from "./components/TopBar.js";
import { Footer } from "./components/Footer.js";
import { GuidedTourModal } from "./components/GuidedTourModal.js";
import { LandingPage } from "./pages/LandingPage.js";
import { AuthPage } from "./pages/AuthPage.js";
import { SignUpPage } from "./pages/SignUpPage.js";
import { FreeSpiritPage } from "./pages/FreeSpiritPage.js";
import { ArchivePage } from "./pages/ArchivePage.js";
import { CasePage } from "./pages/CasePage.js";
import { DashboardPage } from "./pages/DashboardPage.js";
import { NewInvestigationPage } from "./pages/NewInvestigationPage.js";

export function formatOwnerStatus(status: OwnerStatus): { label: string; icon: string } {
  switch (status) {
    case "verified":
      return { label: "Verified", icon: "✓" };
    case "supported":
      return { label: "Supported", icon: "▲" };
    case "conflicting":
      return { label: "Conflicting", icon: "⚠" };
    case "no_evidence":
      return { label: "No Evidence", icon: "○" };
  }
}

// Helper for initial route, caseId, and investigationId from hash
function parseHashRoute(): { route: string; caseId?: string; investigationId?: string } {
  if (typeof window !== "undefined" && window.location.hash) {
    const raw = window.location.hash.replace(/^#\/?/, "");
    const parts = raw.split("?")[0].split("/");
    const base = parts[0];
    const subId = parts[1];

    if (base === "case" && subId) {
      return { route: "case", caseId: subId };
    }
    if (base === "investigation") {
      if (subId === "new") {
        return { route: "new-investigation" };
      }
      if (subId) {
        return { route: "investigation", investigationId: subId };
      }
    }
    if (base === "upload") {
      return { route: "new-investigation" };
    }
    if (base) return { route: base };
  }
  return { route: "landing" };
}

export const App: React.FC = () => {
  const initial = parseHashRoute();
  const [currentRoute, setCurrentRoute] = useState<string>(initial.route);
  const [activeCaseId, setActiveCaseId] = useState<string>(initial.caseId || "case_demo_01");
  const [activeInvestigationId, setActiveInvestigationId] = useState<string>(
    initial.investigationId || "",
  );
  const [demoModalOpen, setDemoModalOpen] = useState<boolean>(false);

  // Sync hash changes with state
  useEffect(() => {
    const handleHashChange = () => {
      const parsed = parseHashRoute();
      setCurrentRoute(parsed.route);
      if (parsed.caseId) {
        setActiveCaseId(parsed.caseId);
      }
      if (parsed.investigationId) {
        setActiveInvestigationId(parsed.investigationId);
      }
    };

    window.addEventListener("hashchange", handleHashChange);
    return () => window.removeEventListener("hashchange", handleHashChange);
  }, []);

  const handleNavigate = (route: string, params?: Record<string, string>) => {
    if (params?.caseId) {
      setActiveCaseId(params.caseId);
    }
    if (params?.id) {
      setActiveInvestigationId(params.id);
    }
    setCurrentRoute(route);

    if (typeof window !== "undefined") {
      let hash = route === "landing" ? "" : route;
      if (route === "case" && params?.caseId) {
        hash = `case/${params.caseId}`;
      } else if (route === "investigation" && params?.id) {
        hash = `investigation/${params.id}`;
      } else if (route === "new-investigation" || (route === "investigation" && params?.action === "new")) {
        hash = "investigation/new";
      }
      window.location.hash = `#/${hash}`;
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        background: "var(--ink)",
        color: "var(--paper)",
        position: "relative",
      }}
    >
      {/* 1. Global Navigation TopBar */}
      <TopBar
        currentRoute={currentRoute}
        onRouteChange={handleNavigate}
        onOpenDemoModal={() => setDemoModalOpen(true)}
      />

      {/* 2. Page Content View */}
      <main style={{ flex: 1 }}>
        {currentRoute === "landing" || currentRoute === "" ? (
          <LandingPage onRouteChange={handleNavigate} onOpenDemo={() => setDemoModalOpen(true)} />
        ) : currentRoute === "dashboard" ? (
          <DashboardPage onRouteChange={handleNavigate} onOpenDemo={() => setDemoModalOpen(true)} />
        ) : currentRoute === "new-investigation" || currentRoute === "upload" ? (
          <NewInvestigationPage onRouteChange={handleNavigate} />
        ) : currentRoute === "investigation" ? (
          <NewInvestigationPage
            investigationId={activeInvestigationId}
            onRouteChange={handleNavigate}
          />
        ) : currentRoute === "auth" || currentRoute === "signin" ? (
          <AuthPage onRouteChange={handleNavigate} onOpenDemoModal={() => setDemoModalOpen(true)} />
        ) : currentRoute === "spirit" ? (
          <FreeSpiritPage onRouteChange={handleNavigate} />
        ) : currentRoute === "signup" ? (
          <SignUpPage
            onRouteChange={handleNavigate}
            onOpenDemoModal={() => setDemoModalOpen(true)}
          />
        ) : currentRoute === "archive" || currentRoute === "chambers" ? (
          <ArchivePage onRouteChange={handleNavigate} />
        ) : currentRoute === "case" || currentRoute.startsWith("case_") ? (
          <CasePage caseId={activeCaseId} onRouteChange={handleNavigate} />
        ) : (
          <div
            className="animate-fade-in"
            style={{
              maxWidth: "640px",
              margin: "60px auto",
              padding: "40px 24px",
              textAlign: "center",
            }}
          >
            <div className="panel" style={{ padding: "44px 30px" }}>
              <div className="eyebrow" style={{ color: "var(--gold)" }}>
                ARCHIVE VAULT CHAMBER
              </div>
              <h2
                className="display"
                style={{ fontSize: "26px", color: "var(--cream)", margin: "12px 0 16px" }}
              >
                {currentRoute.toUpperCase()} SECTION
              </h2>
              <p
                className="serif"
                style={{
                  fontSize: "17px",
                  color: "#cdb78e",
                  maxWidth: "520px",
                  margin: "0 auto 24px",
                  lineHeight: 1.55,
                }}
              >
                This sanctuary chamber is being restored. You can explore the active Four-Chamber
                Registry or Sanctuary Dashboard.
              </p>
              <div style={{ display: "flex", gap: "12px", justifyContent: "center" }}>
                <button
                  onClick={() => handleNavigate("dashboard")}
                  className="btn small"
                >
                  Return to Dashboard
                </button>
                <button
                  onClick={() => handleNavigate("archive")}
                  className="btn secondary small"
                >
                  Chamber Registry
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* 3. Global Guided Tour Modal */}
      <GuidedTourModal isOpen={demoModalOpen} onClose={() => setDemoModalOpen(false)} />

      {/* 4. Global Atmospheric Footer */}
      <Footer onRouteChange={handleNavigate} onOpenDemoModal={() => setDemoModalOpen(true)} />
    </div>
  );
};

