import React, { useState } from "react";

export interface FourChambersPreviewProps {
  onSelectChamber: (chamber: "LOST" | "FORGOTTEN" | "LONELY" | "INNOCENT") => void;
  title?: string;
  subtitle?: string;
}

export const CHAMBER_DEFINITIONS = [
  {
    name: "LOST" as const,
    glyph: "/glyph-lost.png",
    subtitle: "Departed Owner",
    color: "#c49a52",
    explanation:
      "A human owner is verified in historical commits, but HR records confirm their departure. The machine identity retains active, unmanaged access.",
  },
  {
    name: "FORGOTTEN" as const,
    glyph: "/glyph-forgotten.png",
    subtitle: "Missing Provenance",
    color: "#a52c30",
    explanation:
      "Zero human signatures, tickets, or author handles exist in audit records. The key operates with completely unrecorded provenance.",
  },
  {
    name: "LONELY" as const,
    glyph: "/glyph-lonely.png",
    subtitle: "Dormant Privilege",
    color: "#8c6b39",
    explanation:
      "The designated human owner remains active in the organization, but the machine credential has been inactive for over 90 days.",
  },
  {
    name: "INNOCENT" as const,
    glyph: "/glyph-innocent.png",
    subtitle: "Unexpiring Hotfix",
    color: "#7e9272",
    explanation:
      "Provisioned for an emergency release or temporary task with legitimate intent, but left active without an automated expiration window.",
  },
];

export const FourChambersPreview: React.FC<FourChambersPreviewProps> = ({
  onSelectChamber,
  title = "THE FOUR VAULT CHAMBERS",
  subtitle = "Every forgotten machine identity is classified into one of four governance chambers based on verified evidence.",
}) => {
  const [activeChamber, setActiveChamber] = useState<string | null>(null);

  return (
    <div style={{ width: "100%" }}>
      {(title || subtitle) && (
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          {title && (
            <div
              className="eyebrow"
              style={{ color: "var(--gold)", letterSpacing: "0.2em", marginBottom: "8px" }}
            >
              ✦ {title} ✦
            </div>
          )}
          {subtitle && (
            <p
              className="serif"
              style={{
                fontSize: "17px",
                color: "#c7b591",
                maxWidth: "640px",
                margin: "0 auto",
                fontStyle: "italic",
              }}
            >
              {subtitle}
            </p>
          )}
        </div>
      )}

      {/* Grid of four clean minimal chamber illustrations */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(230px, 1fr))",
          gap: "20px",
        }}
      >
        {CHAMBER_DEFINITIONS.map((ch) => {
          const isHovered = activeChamber === ch.name;

          return (
            <div
              key={ch.name}
              role="button"
              tabIndex={0}
              id={`chamber-preview-${ch.name.toLowerCase()}`}
              aria-label={`Explore ${ch.name} Chamber: ${ch.subtitle}`}
              onClick={() => onSelectChamber(ch.name)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onSelectChamber(ch.name);
                }
              }}
              onMouseEnter={() => setActiveChamber(ch.name)}
              onMouseLeave={() => setActiveChamber(null)}
              onFocus={() => setActiveChamber(ch.name)}
              onBlur={() => setActiveChamber(null)}
              style={{
                position: "relative",
                padding: "30px 20px 24px",
                textAlign: "center",
                background: isHovered
                  ? "linear-gradient(180deg, rgba(32, 26, 36, 0.98), rgba(18, 15, 20, 0.98))"
                  : "linear-gradient(180deg, rgba(22, 18, 25, 0.92) 0%, rgba(13, 11, 15, 0.96) 100%)",
                border: isHovered
                  ? "1px solid var(--gold)"
                  : "1px solid rgba(197, 160, 89, 0.3)",
                borderRadius: "4px",
                cursor: "pointer",
                transition: "all 0.25s cubic-bezier(0.16, 1, 0.3, 1)",
                transform: isHovered ? "translateY(-4px)" : "translateY(0)",
                boxShadow: isHovered
                  ? "0 14px 34px rgba(0, 0, 0, 0.8), 0 0 20px rgba(197, 160, 89, 0.2)"
                  : "0 4px 16px rgba(0, 0, 0, 0.5)",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "space-between",
                minHeight: "260px",
              }}
            >
              {/* Glyph Illustration */}
              <div style={{ position: "relative", marginBottom: "16px" }}>
                <img
                  src={ch.glyph}
                  alt={ch.name}
                  style={{
                    width: "80px",
                    height: "80px",
                    objectFit: "contain",
                    filter: isHovered
                      ? `drop-shadow(0 0 16px ${ch.color})`
                      : "drop-shadow(0 0 8px rgba(0,0,0,0.6))",
                    transition: "transform 0.25s ease, filter 0.25s ease",
                    transform: isHovered ? "scale(1.08)" : "scale(1)",
                  }}
                />
              </div>

              {/* Minimal Clean Label */}
              <div style={{ width: "100%" }}>
                <div
                  className="display"
                  style={{
                    fontSize: "20px",
                    fontWeight: 700,
                    letterSpacing: "0.08em",
                    color: isHovered ? "var(--cream)" : "#f0dfbd",
                    marginBottom: "4px",
                  }}
                >
                  {ch.name}
                </div>

                <div
                  className="serif"
                  style={{
                    fontSize: "13px",
                    color: ch.color,
                    fontStyle: "italic",
                    marginBottom: "12px",
                  }}
                >
                  {ch.subtitle}
                </div>

                {/* Hover / Focus Revealed Explanation */}
                <div
                  style={{
                    fontSize: "12px",
                    lineHeight: "1.55",
                    color: "#dcd0b8",
                    padding: "0 8px",
                    minHeight: "48px",
                    opacity: isHovered ? 1 : 0.82,
                    transition: "opacity 0.2s ease",
                  }}
                >
                  {ch.explanation}
                </div>
              </div>

              {/* Action Prompt */}
              <div
                style={{
                  marginTop: "16px",
                  paddingTop: "10px",
                  borderTop: "1px solid rgba(197, 160, 89, 0.2)",
                  width: "100%",
                }}
              >
                <span
                  className="display"
                  style={{
                    fontSize: "10.5px",
                    letterSpacing: "0.08em",
                    color: isHovered ? "var(--gold2)" : "#a99b82",
                    fontWeight: 600,
                  }}
                >
                  Explore Chamber Cases →
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from "react";

export interface AuthModalProps {
  isOpen: boolean;
  initialMode?: "signin" | "signup";
  onClose: () => void;
  onSuccess: () => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({
  isOpen,
  initialMode = "signin",
  onClose,
  onSuccess,
}) => {
  const [mode, setMode] = useState<"signin" | "signup">(initialMode);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<{ email?: string; password?: string; confirm?: string }>({});

  const modalRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setMode(initialMode);
    setErrors({});
  }, [initialMode, isOpen]);

  // Handle Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const validateForm = () => {
    const newErrors: { email?: string; password?: string; confirm?: string } = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!email.trim()) {
      newErrors.email = "Email address is required.";
    } else if (!emailRegex.test(email.trim())) {
      newErrors.email = "Please enter a valid email address.";
    }

    if (!password) {
      newErrors.password = "REDACTED";
    } else if (password.length < 8) {
      newErrors.password = "REDACTED";
    }

    if (mode === "signup" && password !== confirmPassword) {
      newErrors.confirm = "Passwords do not match.";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    setLoading(true);
    // Authentic simulated authentication delay
    setTimeout(() => {
      setLoading(false);
      onSuccess();
      onClose();
    }, 600);
  };

  const handleDemoGuestEntry = () => {
    onSuccess();
    onClose();
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="auth-modal-title"
      style={{
        position: "fixed",
        inset: 0,
        backgroundColor: "rgba(8, 8, 12, 0.88)",
        backdropFilter: "blur(8px)",
        zIndex: 100,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "20px",
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        ref={modalRef}
        className="panel animate-fade-in"
        style={{
          maxWidth: "480px",
          width: "100%",
          padding: "36px",
          border: "1px solid var(--gold)",
          backgroundImage: "linear-gradient(145deg, rgba(32, 26, 33, 0.98), rgba(16, 14, 18, 0.99))",
          boxShadow: "0 24px 60px rgba(0, 0, 0, 0.9), 0 0 30px rgba(197, 160, 89, 0.2)",
          position: "relative",
        }}
      >
        {/* Dismiss Close Button */}
        <button
          type="button"
          onClick={onClose}
          aria-label="Close authentication modal"
          id="btn-close-auth-modal"
          style={{
            position: "absolute",
            top: "16px",
            right: "16px",
            background: "transparent",
            border: "none",
            color: "#a99b82",
            fontSize: "20px",
            cursor: "pointer",
            padding: "4px 8px",
          }}
        >
          ✕
        </button>

        {/* Altar Emblem Header */}
        <div style={{ textAlign: "center", marginBottom: "24px" }}>
          <img
            src="/logo.png"
            alt="Keys of the Departed emblem"
            style={{ width: "48px", height: "52px", objectFit: "contain", margin: "0 auto 12px" }}
          />
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "4px" }}>
            SANCTUARY ACCESS
          </div>
          <h2
            id="auth-modal-title"
            className="display"
            style={{ fontSize: "22px", color: "var(--cream)", margin: 0 }}
          >
            {mode === "signin" ? "Investigator Sign In" : "Register Sanctuary Account"}
          </h2>
        </div>

        {/* Tab Toggle: Sign In vs Sign Up */}
        <div
          style={{
            display: "flex",
            borderBottom: "1px solid var(--line)",
            marginBottom: "24px",
          }}
        >
          <button
            type="button"
            id="tab-auth-signin"
            onClick={() => {
              setMode("signin");
              setErrors({});
            }}
            className="display"
            style={{
              flex: 1,
              padding: "10px",
              background: "transparent",
              border: "none",
              borderBottom: mode === "signin" ? "2px solid var(--gold2)" : "2px solid transparent",
              color: mode === "signin" ? "var(--gold2)" : "#a99b82",
              fontSize: "11px",
              fontWeight: 600,
              letterSpacing: "0.08em",
              cursor: "pointer",
              transition: "all 0.2s",
            }}
          >
            Sign In
          </button>
          <button
            type="button"
            id="tab-auth-signup"
            onClick={() => {
              setMode("signup");
              setErrors({});
            }}
            className="display"
            style={{
              flex: 1,
              padding: "10px",
              background: "transparent",
              border: "none",
              borderBottom: mode === "signup" ? "2px solid var(--gold2)" : "2px solid transparent",
              color: mode === "signup" ? "var(--gold2)" : "#a99b82",
              fontSize: "11px",
              fontWeight: 600,
              letterSpacing: "0.08em",
              cursor: "pointer",
              transition: "all 0.2s",
            }}
          >
            Register
          </button>
        </div>

        {/* Auth0 Sandbox Configuration Notice */}
        <div
          style={{
            padding: "10px 14px",
            background: "rgba(197, 160, 89, 0.12)",
            borderLeft: "3px solid var(--gold)",
            fontSize: "11.5px",
            color: "#ebd6b0",
            marginBottom: "20px",
            lineHeight: 1.45,
          }}
        >
          <strong>Auth0 Integration:</strong> Sandbox Demo Mode active. Enter any credentials to
          continue, or enter directly as a guest investigator.
        </div>

        {/* Authentication Form */}
        <form onSubmit={handleSubmit} noValidate>
          <div style={{ marginBottom: "16px" }}>
            <label
              htmlFor="auth-email"
              style={{
                display: "block",
                fontFamily: "var(--display)",
                fontSize: "10.5px",
                letterSpacing: "0.08em",
                color: "var(--gold2)",
                marginBottom: "6px",
              }}
            >
              EMAIL ADDRESS *
            </label>
            <input
              id="auth-email"
              type="email"
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="investigator@enterprise.corp"
              style={{
                width: "100%",
                padding: "10px 12px",
                background: "rgba(10, 8, 12, 0.8)",
                border: errors.email
                  ? "1px solid var(--crimson2)"
                  : "1px solid rgba(197, 160, 89, 0.4)",
                color: "#f7ebd2",
                borderRadius: "3px",
                fontSize: "13.5px",
              }}
            />
            {errors.email && (
              <div style={{ color: "var(--crimson2)", fontSize: "11.5px", marginTop: "4px" }}>
                {errors.email}
              </div>
            )}
          </div>

          <div style={{ marginBottom: mode === "signup" ? "16px" : "22px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "6px" }}>
              <label
                htmlFor="auth-password"
                style={{
                  fontFamily: "var(--display)",
                  fontSize: "10.5px",
                  letterSpacing: "0.08em",
                  color: "var(--gold2)",
                }}
              >
                PASSWORD *
              </label>
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  background: "transparent",
                  border: "none",
                  color: "var(--gold2)",
                  fontSize: "11px",
                  cursor: "pointer",
                  padding: 0,
                }}
              >
                {showPassword ? "Hide" : "Show"}
              </button>
            </div>
            <input
              id="auth-password"
              type={showPassword ? "text" : "password"}
              autoComplete={mode === "signin" ? "current-password" : "REDACTED"}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Minimum 8 characters"
              style={{
                width: "100%",
                padding: "10px 12px",
                background: "rgba(10, 8, 12, 0.8)",
                border: errors.password
                  ? "1px solid var(--crimson2)"
                  : "1px solid rgba(197, 160, 89, 0.4)",
                color: "#f7ebd2",
                borderRadius: "3px",
                fontSize: "13.5px",
              }}
            />
            {errors.password && (
              <div style={{ color: "var(--crimson2)", fontSize: "11.5px", marginTop: "4px" }}>
                {errors.password}
              </div>
            )}
          </div>

          {mode === "signup" && (
            <div style={{ marginBottom: "22px" }}>
              <label
                htmlFor="auth-confirm-password"
                style={{
                  display: "block",
                  fontFamily: "var(--display)",
                  fontSize: "10.5px",
                  letterSpacing: "0.08em",
                  color: "var(--gold2)",
                  marginBottom: "6px",
                }}
              >
                CONFIRM PASSWORD *
              </label>
              <input
                id="auth-confirm-password"
                type={showPassword ? "text" : "password"}
                autoComplete="REDACTED"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                style={{
                  width: "100%",
                  padding: "10px 12px",
                  background: "rgba(10, 8, 12, 0.8)",
                  border: errors.confirm
                    ? "1px solid var(--crimson2)"
                    : "1px solid rgba(197, 160, 89, 0.4)",
                  color: "#f7ebd2",
                  borderRadius: "3px",
                  fontSize: "13.5px",
                }}
              />
              {errors.confirm && (
                <div style={{ color: "var(--crimson2)", fontSize: "11.5px", marginTop: "4px" }}>
                  {errors.confirm}
                </div>
              )}
            </div>
          )}

          <button
            type="submit"
            id="btn-auth-submit"
            disabled={loading}
            className="btn"
            style={{ width: "100%", padding: "12px", marginBottom: "12px" }}
          >
            {loading ? "Validating..." : mode === "signin" ? "Sign In to Sanctuary" : "Complete Registration"}
          </button>

          <button
            type="button"
            id="btn-auth-guest-demo"
            onClick={handleDemoGuestEntry}
            className="btn secondary small"
            style={{ width: "100%", padding: "10px", fontSize: "10.5px" }}
          >
            ✦ Enter Sanctuary as Demo Investigator
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from "react";

export interface IntegrationsPageProps {
  onRouteChange: (route: string) => void;
}

export type IntegrationStatus = "Implemented" | "Partially implemented" | "Planned" | "Not configured";

export interface PartnerIntegration {
  id: string;
  name: string;
  intendedRole: string;
  status: IntegrationStatus;
