import { Db } from "mongodb";

export const COLLECTIONS = {
  ACCOUNTS: "accounts",
  CASES: "cases",
  RECORDS: "records",
  INVESTIGATIONS: "investigations",
  INVESTIGATION_FILES: "investigation_files",
  INVESTIGATION_FINDINGS: "investigation_findings",
} as const;

/**
 * Creates stable indexes idempotently across collections according to SPEC 4.1.
 */
export async function ensureIndexes(db: Db): Promise<void> {
  const accounts = db.collection(COLLECTIONS.ACCOUNTS);
  await accounts.createIndex({ account_id: 1 }, { unique: true });
  await accounts.createIndex({ ghost_type: 1 });
  await accounts.createIndex({ owner_status: 1 });
  await accounts.createIndex({ ghost_type: 1, owner_status: 1 });

  const cases = db.collection(COLLECTIONS.CASES);
  await cases.createIndex({ case_id: 1 }, { unique: true });
  await cases.createIndex({ account_id: 1 });
  await cases.createIndex({ bundle_id: 1 });

  const records = db.collection(COLLECTIONS.RECORDS);
  await records.createIndex({ record_id: 1 }, { unique: true });
  await records.createIndex({ type: 1 });
  await records.createIndex({ actor_account_id: 1 });
  await records.createIndex({ investigation_id: 1 });

  const investigations = db.collection(COLLECTIONS.INVESTIGATIONS);
  await investigations.createIndex({ investigation_id: 1 }, { unique: true });
  await investigations.createIndex({ status: 1 });
  await investigations.createIndex({ created_at: -1 });

  const files = db.collection(COLLECTIONS.INVESTIGATION_FILES);
  await files.createIndex({ file_id: 1 }, { unique: true });
  await files.createIndex({ investigation_id: 1 });

  const findings = db.collection(COLLECTIONS.INVESTIGATION_FINDINGS);
  await findings.createIndex({ investigation_id: 1 }, { unique: true });
}

import dotenv from "dotenv";
import { loadConfig } from "../config.js";
import { MongoConnectionManager } from "./connection.js";
import { COLLECTIONS, ensureIndexes } from "./collections.js";
import { SYNTHETIC_ACCOUNTS } from "../fixtures/syntheticAccounts.js";
import { SYNTHETIC_CASES, SYNTHETIC_RECORDS } from "../fixtures/syntheticCases.js";

dotenv.config();

/**
 * Explicit seed script for MongoDB Atlas.
 * Never executed automatically at server startup.
 * Safe to run repeatedly (uses deterministic upsert, never overwrites user data).
 */
export async function seedDatabase(): Promise<{
  accountsUpserted: number;
  casesUpserted: number;
  recordsUpserted: number;
}> {
  const config = loadConfig();
  if (!config.MONGODB_URI) {
    throw new Error("MONGODB_URI is not configured in environment. Cannot seed database.");
  }

  const manager = MongoConnectionManager.getInstance();
  const db = await manager.connect(config);
  if (!db) {
    throw new Error("Failed to acquire MongoDB database instance.");
  }

  await ensureIndexes(db);

  let accountsCount = 0;
  const accountsCol = db.collection(COLLECTIONS.ACCOUNTS);
  for (const acc of SYNTHETIC_ACCOUNTS) {
    await accountsCol.updateOne(
      { account_id: acc.account_id },
      {
        $setOnInsert: {
          ...acc,
          is_synthetic: true,
          seeded_at: new Date().toISOString(),
        },
      },
      { upsert: true },
    );
    accountsCount++;
  }

  let casesCount = 0;
  const casesCol = db.collection(COLLECTIONS.CASES);
  for (const caseData of Object.values(SYNTHETIC_CASES)) {
    await casesCol.updateOne(
      { case_id: caseData.case_id },
      {
        $setOnInsert: {
          ...caseData,
          is_synthetic: true,
          seeded_at: new Date().toISOString(),
        },
      },
      { upsert: true },
    );
    casesCount++;
  }

  let recordsCount = 0;
  const recordsCol = db.collection(COLLECTIONS.RECORDS);
  for (const record of Object.values(SYNTHETIC_RECORDS)) {
    await recordsCol.updateOne(
      { record_id: record.record_id },
      {
        $setOnInsert: {
          ...record,
          is_synthetic: true,
          seeded_at: new Date().toISOString(),
        },
      },
      { upsert: true },
    );
    recordsCount++;
  }

  return {
    accountsUpserted: accountsCount,
    casesUpserted: casesCount,
    recordsUpserted: recordsCount,
  };
}

// Direct execution from CLI
if (process.argv[1] && process.argv[1].includes("seed")) {
  seedDatabase()
    .then((counts) => {
      console.log(
        `[keys-of-the-departed] Seed complete: ${counts.accountsUpserted} accounts, ${counts.casesUpserted} cases, ${counts.recordsUpserted} records registered.`,
      );
      process.exit(0);
    })
    .catch((err) => {
      console.error(
        "[keys-of-the-departed] Seed failed:",
        err instanceof Error ? err.message : "Unknown error",
      );
      process.exit(1);
    });
}

import { Db, Filter } from "mongodb";
import { AccountsQuery, AccountsResponse, ArchiveAccount, ArchiveAccountSchema } from "@keys/contracts";
import { AccountsRepository } from "./accountsRepository.js";
import { COLLECTIONS } from "../db/collections.js";

export class MongoAccountsRepository implements AccountsRepository {
  constructor(private readonly db: Db) {}

  async findAccounts(query: AccountsQuery): Promise<AccountsResponse> {
    const { chapter, status, search, page, limit } = query;
    const filter: Filter<any> = {};

    // 1. Chapter filter
    if (chapter && chapter !== "ALL") {
      filter.ghost_type = chapter;
    }

    // 2. Owner status filter
    if (status && status !== "ALL") {
      filter.owner_status = status;
    }

    // 3. Search query with safe regex escaping (prevent ReDoS & query injection)
    const cleanSearch = search?.trim();
    if (cleanSearch) {
      const escaped = cleanSearch.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const searchRegex = new RegExp(escaped, "i");
      filter.$or = [
        { account_id: searchRegex },
        { owner_name: searchRegex },
        { purpose: searchRegex },
        { primary_quote: searchRegex },
        { kind: searchRegex },
        { tags: searchRegex },
      ];
    }

    const collection = this.db.collection(COLLECTIONS.ACCOUNTS);

    // Count matching documents
    const total = await collection.countDocuments(filter);
    const totalPages = Math.ceil(total / limit);
    const skip = (page - 1) * limit;

    // Fetch paginated documents, strictly stripping MongoDB _id
    const docs = await collection
      .find(filter, { projection: { _id: 0, is_synthetic: 0, seeded_at: 0 } })
      .sort({ account_id: 1 })
      .skip(skip)
      .limit(limit)
      .toArray();

    // Validate documents against shared contract
    const data: ArchiveAccount[] = [];
    for (const doc of docs) {
      const parsed = ArchiveAccountSchema.safeParse(doc);
      if (parsed.success) {
        data.push(parsed.data);
      }
    }

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  async findAccountById(id: string): Promise<ArchiveAccount | null> {
    const collection = this.db.collection(COLLECTIONS.ACCOUNTS);
    const doc = await collection.findOne(
      { account_id: id },
      { projection: { _id: 0, is_synthetic: 0, seeded_at: 0 } },
    );

    if (!doc) {
      return null;
    }

    const parsed = ArchiveAccountSchema.safeParse(doc);
    return parsed.success ? parsed.data : null;
  }
}

import { Db } from "mongodb";
import { Case, CaseSchema, EvidenceRecord, EvidenceRecordSchema } from "@keys/contracts";
import { CasesRepository } from "./casesRepository.js";
import { COLLECTIONS } from "../db/collections.js";

export class MongoCasesRepository implements CasesRepository {
  constructor(private readonly db: Db) {}

  async findCaseById(id: string): Promise<Case | null> {
    const collection = this.db.collection(COLLECTIONS.CASES);
    const doc = await collection.findOne(
      { case_id: id },
      { projection: { _id: 0, is_synthetic: 0, seeded_at: 0 } },
    );

    if (!doc) {
      return null;
    }

    const parsed = CaseSchema.safeParse(doc);
    return parsed.success ? parsed.data : null;
  }

  async findRecordById(id: string): Promise<EvidenceRecord | null> {
    const collection = this.db.collection(COLLECTIONS.RECORDS);
    const doc = await collection.findOne(
      { record_id: id },
      { projection: { _id: 0, is_synthetic: 0, seeded_at: 0 } },
    );

    if (!doc) {
      return null;
    }

    const parsed = EvidenceRecordSchema.safeParse(doc);
    return parsed.success ? parsed.data : null;
  }

  async findRecordsByCaseId(caseId: string): Promise<EvidenceRecord[]> {
    const caseDoc = await this.findCaseById(caseId);
    if (!caseDoc) {
      return [];
    }

    const recordIds = new Set<string>();
    caseDoc.claims_accepted.forEach((cl) => recordIds.add(cl.record_id));
    caseDoc.claims_removed.forEach((cl) => recordIds.add(cl.record_id));

    if (recordIds.size === 0) {
      return [];
    }

    const collection = this.db.collection(COLLECTIONS.RECORDS);
    const docs = await collection
      .find(
        { record_id: { $in: Array.from(recordIds) } },
        { projection: { _id: 0, is_synthetic: 0, seeded_at: 0 } },
      )
      .toArray();

    const results: EvidenceRecord[] = [];
    for (const doc of docs) {
      const parsed = EvidenceRecordSchema.safeParse(doc);
      if (parsed.success) {
        results.push(parsed.data);
      }
    }

    return results;
  }
}

import path from "path";
import { Db } from "mongodb";
import {
  CreateInvestigationInput,
  DashboardStats,
  DashboardStatsSchema,
  EvidenceRecord,
  EvidenceRecordSchema,
  EvidenceRecordType,
  Investigation,
  InvestigationFindings,
  InvestigationFindingsSchema,
  InvestigationSchema,
  SingleFileInput,
  UploadedFile,
  UploadedFileSchema,
  ArchiveAccount,
  ArchiveAccountSchema,
  Case,
  CaseSchema,
} from "@keys/contracts";
import { InvestigationsRepository } from "./investigationsRepository.js";
