import dotenv from "dotenv";
import { loadConfig } from "./config.js";
import { createApp } from "./app.js";
import { MongoConnectionManager } from "./db/connection.js";
import { ensureIndexes } from "./db/collections.js";
import {
  AccountsRepository,
  FixtureAccountsRepository,
} from "./repositories/accountsRepository.js";
import { CasesRepository, FixtureCasesRepository } from "./repositories/casesRepository.js";
import {
  InvestigationsRepository,
  FixtureInvestigationsRepository,
} from "./repositories/investigationsRepository.js";
import { MongoAccountsRepository } from "./repositories/mongoAccountsRepository.js";
import { MongoCasesRepository } from "./repositories/mongoCasesRepository.js";
import { MongoInvestigationsRepository } from "./repositories/mongoInvestigationsRepository.js";
import { DependencyCheckers } from "./health.js";

dotenv.config();

async function startServer() {
  const config = loadConfig();
  const connectionManager = MongoConnectionManager.getInstance();

  let accountsRepo: AccountsRepository = new FixtureAccountsRepository();
  let casesRepo: CasesRepository = new FixtureCasesRepository();
  let investigationsRepo: InvestigationsRepository = new FixtureInvestigationsRepository();
  const checkers: DependencyCheckers = {};

  if (config.MONGODB_URI) {
    try {
      console.log("[keys-of-the-departed] Connecting to MongoDB Atlas...");
      const db = await connectionManager.connect(config);
      if (db) {
        await ensureIndexes(db);
        accountsRepo = new MongoAccountsRepository(db);
        casesRepo = new MongoCasesRepository(db);
        investigationsRepo = new MongoInvestigationsRepository(db);

        checkers.checkDb = async () => {
          const isAlive = await connectionManager.ping();
          return isAlive ? "ok" : "unavailable";
        };

        console.log(
          `[keys-of-the-departed] Connected to MongoDB database: ${config.MONGODB_DB_NAME}`,
        );
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Connection failed";
      console.warn(
        `[keys-of-the-departed] MongoDB connection failed; falling back to in-memory fixtures. (${msg})`,
      );
      checkers.checkDb = async () => "unavailable";
    }
  } else {
    console.log(
      "[keys-of-the-departed] MONGODB_URI not configured. Running in core in-memory demo mode.",
    );
  }

  const app = createApp(config, checkers, accountsRepo, casesRepo, investigationsRepo);

  const server = app.listen(config.PORT, () => {
    console.log(
      `[keys-of-the-departed] Server listening on port ${config.PORT} (mode: ${config.NODE_ENV})`,
    );
  });

  server.on("error", (err: NodeJS.ErrnoException) => {
    if (err.code === "EADDRINUSE") {
      console.error(
        `Port ${config.PORT} is already in use. Please select a different port via PORT environment variable.`,
      );
      process.exit(1);
    } else {
      console.error("Server startup error:", err.message);
      process.exit(1);
    }
  });

  // Graceful shutdown handling
  const shutdown = async (signal: string) => {
    console.log(`\n[keys-of-the-departed] Received ${signal}. Initiating graceful shutdown...`);
    server.close(async () => {
      console.log("[keys-of-the-departed] HTTP server closed.");
      await connectionManager.disconnect();
      console.log("[keys-of-the-departed] Database connections closed. Process terminating.");
      process.exit(0);
    });

    // Force exit after 5s if connections hang
    setTimeout(() => {
      console.error("[keys-of-the-departed] Forcefully terminating after timeout.");
      process.exit(1);
    }, 5000).unref();
  };

  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

startServer().catch((err: unknown) => {
  if (err instanceof Error) {
    console.error("Fatal startup error:", err.message);
  } else {
    console.error("Unknown fatal error starting server");
  }
  process.exit(1);
});

import { Db, Collection, Filter } from "mongodb";

/**
 * High-fidelity in-memory MongoDB test double implementing Db and Collection interfaces.
 * Allows exhaustive integration testing of MongoAccountsRepository, MongoCasesRepository,
 * and MongoInvestigationsRepository without requiring network access or external binary downloads.
 */
export class InMemoryMongoDb {
  private collections: Map<string, any[]> = new Map();
  public pingShouldFail = false;

  public getDb(): Db {
    return {
      collection: (name: string) => this.getCollection(name) as unknown as Collection<any>,
      command: async (cmd: any) => {
        if (cmd.ping) {
          if (this.pingShouldFail) {
            throw new Error("Simulated MongoDB ping failure (connection refused)");
          }
          return { ok: 1 };
        }
        return { ok: 1 };
      },
    } as unknown as Db;
  }

  public getCollection(name: string): any {
    if (!this.collections.has(name)) {
      this.collections.set(name, []);
    }
    const docs = this.collections.get(name)!;

    return {
      createIndex: async (_spec: any, _opts?: any) => "index_ok",
      countDocuments: async (filter?: Filter<any>) => {
        return this.matchFilter(docs, filter || {}).length;
      },
      findOne: async (filter: Filter<any>, opts?: any) => {
        const matches = this.matchFilter(docs, filter);
        if (matches.length === 0) return null;
        return this.project(matches[0], opts?.projection);
      },
      find: (filter: Filter<any>, opts?: any) => {
        let results = this.matchFilter(docs, filter);

        const cursor = {
          sort: (sortSpec: Record<string, number>) => {
            const [key, dir] = Object.entries(sortSpec)[0] || [];
            if (key) {
              results.sort((a, b) => {
                if (a[key] < b[key]) return dir === 1 ? -1 : 1;
                if (a[key] > b[key]) return dir === 1 ? 1 : -1;
                return 0;
              });
            }
            return cursor;
          },
          skip: (n: number) => {
            results = results.slice(n);
            return cursor;
          },
          limit: (n: number) => {
            results = results.slice(0, n);
            return cursor;
          },
          toArray: async () => {
            return results.map((d) => this.project(d, opts?.projection));
          },
        };
        return cursor;
      },
      insertOne: async (doc: any) => {
        const cloned = { _id: `id_${Math.random()}`, ...doc };
        docs.push(cloned);
        return { acknowledged: true, insertedId: cloned._id };
      },
      insertMany: async (newDocs: any[]) => {
        const cloned = newDocs.map((d) => ({ _id: `id_${Math.random()}`, ...d }));
        docs.push(...cloned);
        return { acknowledged: true, insertedCount: cloned.length };
      },
      updateOne: async (filter: Filter<any>, update: any, opts?: { upsert?: boolean }) => {
        const idx = docs.findIndex((d) => this.matchesDoc(d, filter));
        if (idx !== -1) {
          if (update.$set) {
            docs[idx] = { ...docs[idx], ...update.$set };
          }
          return { acknowledged: true, matchedCount: 1, modifiedCount: 1, upsertedCount: 0 };
        } else if (opts?.upsert) {
          const newDoc: any = { _id: `id_${Math.random()}` };
          if (update.$setOnInsert) Object.assign(newDoc, update.$setOnInsert);
          if (update.$set) Object.assign(newDoc, update.$set);
          docs.push(newDoc);
          return { acknowledged: true, matchedCount: 0, modifiedCount: 0, upsertedCount: 1 };
        }
        return { acknowledged: true, matchedCount: 0, modifiedCount: 0, upsertedCount: 0 };
      },
      updateMany: async (filter: Filter<any>, update: any) => {
        let count = 0;
        for (let i = 0; i < docs.length; i++) {
          if (this.matchesDoc(docs[i], filter)) {
            if (update.$set) {
              docs[i] = { ...docs[i], ...update.$set };
            }
            count++;
          }
        }
        return { acknowledged: true, matchedCount: count, modifiedCount: count };
      },
    };
  }

  private matchFilter(docs: any[], filter: Filter<any>): any[] {
    return docs.filter((d) => this.matchesDoc(d, filter));
  }

  private matchesDoc(doc: any, filter: Filter<any>): boolean {
    if (!filter || Object.keys(filter).length === 0) return true;

    for (const [key, value] of Object.entries(filter)) {
      if (key === "$or" && Array.isArray(value)) {
        const orMatches = value.some((subFilter) => this.matchesDoc(doc, subFilter));
        if (!orMatches) return false;
        continue;
      }

      if (value && typeof value === "object") {
        if (value instanceof RegExp) {
          const target = String(doc[key] ?? "");
          if (!value.test(target)) return false;
          continue;
        }

        if ("$regex" in value) {
          const reg = new RegExp(value.$regex, value.$options || "i");
          const target = Array.isArray(doc[key]) ? doc[key].join(" ") : String(doc[key] ?? "");
          if (!reg.test(target)) return false;
          continue;
        }

        if ("$in" in value && Array.isArray(value.$in)) {
          if (!value.$in.includes(doc[key])) return false;
          continue;
        }
      }

      if (doc[key] !== value) {
        return false;
      }
    }

    return true;
  }

  private project(doc: any, projection?: Record<string, number>): any {
    if (!projection) return { ...doc };
    const result: any = { ...doc };
    for (const [k, v] of Object.entries(projection)) {
      if (v === 0) {
        delete result[k];
      }
    }
    return result;
  }
}

import { describe, it, expect, beforeEach } from "vitest";
import { InMemoryMongoDb } from "./testMongoDb.js";
import { MongoAccountsRepository } from "../../server/src/repositories/mongoAccountsRepository.js";
import { MongoCasesRepository } from "../../server/src/repositories/mongoCasesRepository.js";
import { MongoInvestigationsRepository } from "../../server/src/repositories/mongoInvestigationsRepository.js";
import { MongoConnectionManager } from "../../server/src/db/connection.js";
import { loadConfig } from "../../server/src/config.js";
import { computeHealthStatus } from "../../server/src/health.js";
import { COLLECTIONS, ensureIndexes } from "../../server/src/db/collections.js";
import { ArchiveAccount, Case, EvidenceRecord } from "@keys/contracts";

describe("MongoDB Atlas Integration & Repositories", () => {
  let memoryDb: InMemoryMongoDb;

  beforeEach(() => {
    memoryDb = new InMemoryMongoDb();
  });

  describe("Connection Manager & Safe Health Verification", () => {
    it("MONGO-01: Does not attempt connection when MONGODB_URI is undefined", async () => {
      const manager = MongoConnectionManager.getInstance();
      const config = loadConfig({ NODE_ENV: "test" });
      const db = await manager.connect(config);

      expect(db).toBeNull();
      expect(manager.isConnected()).toBe(false);
    });

    it("MONGO-02: Real database ping distinguishes healthy, failing, and not_configured states", async () => {
      const startTime = Date.now();
      const demoConfig = loadConfig({ NODE_ENV: "test" });

      // Unconfigured returns 200 with not_configured
      const unconfiguredHealth = await computeHealthStatus(demoConfig, startTime);
      expect(unconfiguredHealth.httpStatus).toBe(200);
      expect(unconfiguredHealth.status.checks.db).toBe("not_configured");

      // Configured with failing ping returns 503 and unavailable
      const configuredConfig = loadConfig({
        NODE_ENV: "test",
        MONGODB_URI: "REDACTED",
      });

      const failingHealth = await computeHealthStatus(configuredConfig, startTime, {
        checkDb: async () => {
          memoryDb.pingShouldFail = true;
          try {
            await memoryDb.getDb().command({ ping: 1 });
            return "ok";
          } catch {
            return "unavailable";
          }
        },
      });

      expect(failingHealth.httpStatus).toBe(503);
      expect(failingHealth.status.status).toBe("unavailable");
      expect(failingHealth.status.checks.db).toBe("unavailable");

      // Configured with successful ping returns 200 and ok
      memoryDb.pingShouldFail = false;
      const successHealth = await computeHealthStatus(configuredConfig, startTime, {
        checkDb: async () => {
          await memoryDb.getDb().command({ ping: 1 });
          return "ok";
        },
      });

      expect(successHealth.httpStatus).toBe(200);
      expect(successHealth.status.status).toBe("ok");
      expect(successHealth.status.checks.db).toBe("ok");
    });

    it("MONGO-03: Connection error logs sanitize credentials and never leak passwords", async () => {
      const manager = MongoConnectionManager.getInstance();
      const badConfig = loadConfig({
        NODE_ENV: "test",
        MONGODB_URI: "REDACTED",
      });

      try {
        await manager.connect(badConfig);
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : String(err);
        expect(msg).not.toContain("super_secret_password_123");
      }
    });

    it("MONGO-04: Indexes are ensured idempotently across all collections", async () => {
      const db = memoryDb.getDb();
      await expect(ensureIndexes(db)).resolves.not.toThrow();
    });
  });

  describe("MongoAccountsRepository", () => {
    const sampleAccount: ArchiveAccount = {
      account_id: "acc_mongo_test_01",
      ghost_type: "LOST",
      owner_status: "verified",
      owner_name: "Sarah Chen",
      purpose: "Production database replica backup deploy key",
      primary_quote: "Signed-off-by: Sarah Chen in commit 8f92ab01",
      kind: "deploy_key",
      tags: ["backup", "postgres", "production"],
      case_id: "case_mongo_test_01",
    };

    beforeEach(async () => {
      const db = memoryDb.getDb();
      await db.collection(COLLECTIONS.ACCOUNTS).insertOne(sampleAccount);
    });

    it("MONGO-05: Queries single account by ID and strips internal _id", async () => {
      const repo = new MongoAccountsRepository(memoryDb.getDb());
      const account = await repo.findAccountById("acc_mongo_test_01");

      expect(account).not.toBeNull();
      expect(account?.account_id).toBe("acc_mongo_test_01");
      expect((account as any)._id).toBeUndefined();
      expect(account?.owner_name).toBe("Sarah Chen");
    });

    it("MONGO-06: Filters accounts by chamber and status with pagination", async () => {
      const repo = new MongoAccountsRepository(memoryDb.getDb());

      const resAll = await repo.findAccounts({
        chapter: "ALL",
        status: "ALL",
        search: "",
        page: 1,
        limit: 10,
      });

      expect(resAll.data).toHaveLength(1);
      expect(resAll.pagination.total).toBe(1);

      // Filtering by a different chapter returns empty
      const resForgotten = await repo.findAccounts({
        chapter: "FORGOTTEN",
        status: "ALL",
        search: "",
        page: 1,
        limit: 10,
      });
      expect(resForgotten.data).toHaveLength(0);
      expect(resForgotten.pagination.total).toBe(0);
    });

    it("MONGO-07: Safe search query escaping handles regex special characters without crashing", async () => {
      const repo = new MongoAccountsRepository(memoryDb.getDb());

      // Should not throw or cause regex syntax error with parenthesis or brackets
      const res = await repo.findAccounts({
        chapter: "ALL",
        status: "ALL",
        search: "Sarah (Chen) [backup]+",
        page: 1,
        limit: 10,
      });

      expect(res.data).toBeDefined();
    });
  });

  describe("MongoCasesRepository", () => {
    const sampleRecord: EvidenceRecord = {
      record_id: "rec_audit_01",
      type: "commit",
      ts: "2026-10-25T10:00:00.000Z",
      author_handle: "schen",
      assignee_handle: null,
      actor_account_id: "acc_mongo_test_01",
      content: "commit 8f92ab01\nAuthor: Sarah Chen <schen@internal.corp>\nAdd backup key.",
      structured: false,
    };

    const sampleCase: Case = {
      case_id: "case_mongo_test_01",
      bundle_id: "bundle_synth_01",
      account_id: "acc_mongo_test_01",
      claims_accepted: [
        {
          kind: "owner",
          account_id: "acc_mongo_test_01",
          person_id: "person_schen",
          record_id: "rec_audit_01",
          quote: "Author: Sarah Chen <schen@internal.corp>",
          text: "Evidence confirms Sarah Chen created this key.",
        },
      ],
      claims_removed: [],
      owner_status: "verified",
      purpose_status: "verified",
      ghost_type: "LOST",
      model: "gemma3:4b",
      latency_ms: 120,
    };

    beforeEach(async () => {
      const db = memoryDb.getDb();
      await db.collection(COLLECTIONS.CASES).insertOne(sampleCase);
      await db.collection(COLLECTIONS.RECORDS).insertOne(sampleRecord);
    });

    it("MONGO-08: Queries case by ID and retrieves linked evidence records", async () => {
      const repo = new MongoCasesRepository(memoryDb.getDb());
      const caseDoc = await repo.findCaseById("case_mongo_test_01");

      expect(caseDoc).not.toBeNull();
      expect(caseDoc?.case_id).toBe("case_mongo_test_01");

      const records = await repo.findRecordsByCaseId("case_mongo_test_01");
      expect(records).toHaveLength(1);
      expect(records[0].record_id).toBe("rec_audit_01");
      expect((records[0] as any)._id).toBeUndefined();
    });

    it("MONGO-09: Returns null and empty arrays for unknown cases and records", async () => {
      const repo = new MongoCasesRepository(memoryDb.getDb());
      expect(await repo.findCaseById("case_nonexistent")).toBeNull();
      expect(await repo.findRecordById("rec_nonexistent")).toBeNull();
      expect(await repo.findRecordsByCaseId("case_nonexistent")).toEqual([]);
    });
  });

  describe("MongoInvestigationsRepository & Persistence Across Recreation", () => {
    it("MONGO-10: Creates investigation, ingests source files, and processes findings in MongoDB", async () => {
      const db = memoryDb.getDb();
      const repo = new MongoInvestigationsRepository(db);

      // 1. Create investigation
      const inv = await repo.createInvestigation({
        name: "Security Audit Q4",
        description: "Post-incident credentials review",
      });

      expect(inv.investigation_id).toBeDefined();
      expect(inv.status).toBe("created");

      // 2. Upload and parse records
      const uploadResult = await repo.addUploadedFiles(inv.investigation_id, [
        {
          filename: "audit_commits.log",
          content: "Author: Marcus Vance <marcus@internal.corp>\nAdd key for acc_deploy_key_881.",
        },
      ]);

      expect(uploadResult.files).toHaveLength(1);
      expect(uploadResult.extracted_records).toHaveLength(1);
      expect(uploadResult.errors).toHaveLength(0);

