import dotenv from "dotenv";
import { loadConfig } from "./server/src/config.js";
import { MongoConnectionManager } from "./server/src/db/connection.js";

dotenv.config({ path: "server/.env" });

async function verifyLiveConnection() {
  const config = loadConfig(process.env);
  if (!config.MONGODB_URI) {
    console.log("Result: MONGODB_URI is not set in server/.env");
    return;
  }

  const manager = MongoConnectionManager.getInstance();
  try {
    const db = await manager.connect(config);
    if (!db) {
      console.log("Result: Manager returned null db");
      return;
    }
    const pingOk = await manager.ping();
    console.log(`Result: MongoDB Atlas Ping ${pingOk ? "SUCCESS (HTTP/Command OK 1)" : "FAILED"}`);
    console.log(`Database Name: ${config.MONGODB_DB_NAME}`);
    await manager.disconnect();
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.log(`Result: MongoDB Atlas Connection Error: ${msg}`);
  }
}

verifyLiveConnection();

